    function setMenuDropdownOpen(menuButton, dropdownMenu, isOpen) {
      dropdownMenu.hidden = !isOpen;
      menuButton.setAttribute('aria-expanded', String(isOpen));
    }

    const simulatedClockWeekdays = Object.freeze(['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']);
    let simulatedClockWeekdayIndex = 6;
    let simulatedClockHour = 16;
    let simulatedClockMinute = 32;
    let simulatedClockSecond = 59;

    function formatSimulatedMenuClock() {
      const period = simulatedClockHour >= 12 ? 'PM' : 'AM';
      let hour12 = simulatedClockHour % 12;
      if (hour12 === 0) {
        hour12 = 12;
      }
      const minuteText = simulatedClockMinute < 10
        ? `0${simulatedClockMinute}`
        : String(simulatedClockMinute);
      return `${simulatedClockWeekdays[simulatedClockWeekdayIndex]} ${hour12}:${minuteText} ${period}`;
    }

    function renderSimulatedMenuClock() {
      if (!menuBarClock) {
        return;
      }
      menuBarClock.textContent = formatSimulatedMenuClock();
      renderDashboardClock();
    }

    function tickSimulatedMenuClock() {
      simulatedClockSecond += 1;
      if (simulatedClockSecond >= 60) {
        simulatedClockSecond = 0;
        simulatedClockMinute += 1;
      }
      if (simulatedClockMinute >= 60) {
        simulatedClockMinute = 0;
        simulatedClockHour += 1;
      }
      if (simulatedClockHour >= 24) {
        simulatedClockHour = 0;
        simulatedClockWeekdayIndex = (simulatedClockWeekdayIndex + 1) % simulatedClockWeekdays.length;
      }
      renderSimulatedMenuClock();
    }

    let arrangeBySubmenuCloseTimer;

