    function closeRecentItemsSubmenuForOtherAppleItems(event) {
      const hoveredAppleMenuItem = event.target.closest('.apple-menu-item');
      if (hoveredAppleMenuItem && hoveredAppleMenuItem !== recentItemsMenuItem) {
        closeRecentItemsSubmenu();
      }
    }

    function activateRecentItemMenuItem(fileSystemObject) {
      if (!isSimulatedRecentItemOpenable(fileSystemObject)) {
        return;
      }
      closeAllMenuDropdowns();
      recordSimulatedRecentItem(fileSystemObject);
      const openingSourceFileSystemObject = getPastedFileSystemObjectSource(fileSystemObject);
      if (openingSourceFileSystemObject === safariFileSystemObject) {
        showSafariWindow();
        return;
      }
      if (openingSourceFileSystemObject === textEditFileSystemObject) {
        showTextEditWindow();
        return;
      }
      if (openingSourceFileSystemObject === calculatorApplicationIdentity) {
        showCalculatorWindow();
        return;
      }
      if (openingSourceFileSystemObject === iTunesApplicationIdentity) {
        showITunesWindow();
        return;
      }
      if (openingSourceFileSystemObject === pagesApplicationIdentity) {
        showPagesWindow();
        return;
      }
      if (isPagesDocument(openingSourceFileSystemObject) || isPagesDocument(fileSystemObject)) {
        showPagesWindow(fileSystemObject);
        return;
      }
      if (openingSourceFileSystemObject === keynoteApplicationIdentity) {
        showKeynoteWindow();
        return;
      }
      if (isKeynoteDocument(openingSourceFileSystemObject) || isKeynoteDocument(fileSystemObject)) {
        showKeynoteWindow(fileSystemObject);
        return;
      }
      if (openingSourceFileSystemObject === numbersApplicationIdentity) {
        showNumbersWindow();
        return;
      }
      if (isNumbersDocument(openingSourceFileSystemObject) || isNumbersDocument(fileSystemObject)) {
        showNumbersWindow(fileSystemObject);
        return;
      }
      if (openingSourceFileSystemObject === iPhotoApplicationIdentity) {
        showIPhotoWindow();
        return;
      }
      if (openingSourceFileSystemObject === iMovieApplicationIdentity) {
        showIMovieWindow();
        return;
      }
      if (isIMovieDocument(openingSourceFileSystemObject) || isIMovieDocument(fileSystemObject)) {
        showIMovieWindow(fileSystemObject);
        return;
      }
      if (openingSourceFileSystemObject === garageBandApplicationIdentity) {
        showGarageBandWindow();
        return;
      }
      if (isGarageBandDocument(openingSourceFileSystemObject) || isGarageBandDocument(fileSystemObject)) {
        showGarageBandWindow(fileSystemObject);
        return;
      }
      if (openingSourceFileSystemObject === iDVDApplicationIdentity) {
        showIDVDWindow();
        return;
      }
      if (isIDVDDocument(openingSourceFileSystemObject) || isIDVDDocument(fileSystemObject)) {
        showIDVDWindow(fileSystemObject);
        return;
      }
      if (openingSourceFileSystemObject === dashboardApplicationIdentity) {
        openDashboard();
        return;
      }
      if (openingSourceFileSystemObject === welcomeFileSystemObject || fileSystemObject.type === 'file') {
        showTextEditWindow(fileSystemObject);
        return;
      }
      if (
        fileSystemObject.type === 'folder' ||
        fileSystemObject.type === 'drive' ||
        fileSystemObject.type === 'system'
      ) {
        const activeFinderWindow = document.querySelector(
          '.finder-window.is-active[data-finder-window="true"]'
        );
        if (activeFinderWindow) {
          navigateFinderWindowToDirectory(activeFinderWindow, fileSystemObject);
          return;
        }
        if (fileSystemObject === macintoshHDFileSystemObject) {
          showMacintoshHDWindow();
          return;
        }
        if (fileSystemObject === applicationsFileSystemObject) {
          showApplicationsWindow();
          return;
        }
        if (fileSystemObject === documentsFileSystemObject) {
          showDocumentsWindow();
          return;
        }
        if (fileSystemObject === trashFileSystemObject) {
          showTrashWindow();
          return;
        }
        showDynamicFolderWindow(fileSystemObject);
        return;
      }
      openFileSystemObject(fileSystemObject);
    }

