      const finderContent = activeFinderWindow.querySelector('.finder-content');
      if (
        !finderContent ||
        activeFinderWindow.getAttribute('data-view-mode') !== 'icons' ||
        !finderContent.classList.contains('is-icon-view')
      ) {
        return;
      }

      applyFinderIconGridPositions(
        finderContent,
        getDirectFinderItems(finderContent)
      );
      finderContent.classList.add('is-cleaned-up');
