    function selectMacintoshHD() {
      macintoshHD.classList.add('is-selected');
      macintoshHD.setAttribute('aria-pressed', 'true');
    }

    function deselectMacintoshHD() {
      macintoshHD.classList.remove('is-selected');
      macintoshHD.setAttribute('aria-pressed', 'false');
    }

    function clearDesktopSelectionOnEmptyClick(contentArea) {
      contentArea.addEventListener('click', (event) => {
        if (event.target === contentArea) {
          deselectMacintoshHD();
        }
      });
    }

    let topWindowZIndex = 10;

    function isFinderOwnedWindow(finderWindow) {
      if (!finderWindow || !finderWindow.classList.contains('finder-window')) {
        return false;
      }
      if (finderWindow.getAttribute('data-finder-window') === 'true') {
        return true;
      }
      if (finderWindow.getAttribute('data-view-options-window') === 'true') {
        return true;
      }
      if (finderWindow.getAttribute('data-get-info-window') === 'true') {
        return true;
      }
      if (finderWindow.getAttribute('data-clipboard-window') === 'true') {
        return true;
      }
      if (finderWindow.getAttribute('data-finder-preferences-window') === 'true') {
        return true;
      }
      return finderWindow.classList.contains('about-finder-window');
    }

    function revealFinderWindowsHiddenByFinder() {
      document.querySelectorAll('.finder-window[data-hidden-by-finder="true"]').forEach((hiddenWindow) => {
        hiddenWindow.classList.remove('is-minimized');
        hiddenWindow.removeAttribute('aria-hidden');
        hiddenWindow.removeAttribute('data-hidden-by-finder');
      });
    }

    function hideFinderWindows() {
      const visibleFinderOwnedWindows = [...document.querySelectorAll('.finder-window')].filter((finderWindow) => (
        isFinderOwnedWindow(finderWindow) &&
        finderWindow.isConnected &&
        !finderWindow.classList.contains('is-minimized')
      ));
      if (visibleFinderOwnedWindows.length === 0) {
        return;
      }

      visibleFinderOwnedWindows.forEach((finderWindow) => {
        finderWindow.classList.add('is-minimized');
        finderWindow.classList.remove('is-active');
        finderWindow.setAttribute('aria-hidden', 'true');
        finderWindow.setAttribute('data-hidden-by-finder', 'true');
      });
    }

    function quitFinderWindows() {
      const finderOwnedWindows = [...document.querySelectorAll('.finder-window')].filter((finderWindow) => (
        isFinderOwnedWindow(finderWindow) && finderWindow.isConnected
      ));
      if (finderOwnedWindows.length === 0) {
        return;
      }

      finderOwnedWindows.forEach((finderWindow) => {
        if (finderWindow.isConnected) {
          closeFinderWindow(finderWindow);
        }
      });
    }

    function restoreFinderWindowsHiddenByFinderIfAny() {
      const hiddenFinderWindows = [...document.querySelectorAll('.finder-window[data-hidden-by-finder="true"]')];
      if (hiddenFinderWindows.length === 0) {
        return false;
      }

      const macintoshHDWindow = document.getElementById('macintosh-hd-window');
      if (macintoshHDWindow && macintoshHDWindow.isConnected) {
        focusFinderWindow(macintoshHDWindow);
        return true;
      }

      revealFinderWindowsHiddenByFinder();
      const finderWindows = [...document.querySelectorAll('[data-finder-window="true"]')].filter((finderWindow) => (
        finderWindow.isConnected
      ));
      if (finderWindows.length === 0) {
        return false;
      }

      const topFinderWindow = finderWindows.reduce((topWindow, candidateWindow) => {
        const topZIndex = Number(topWindow.style.zIndex) || 10;
        const candidateZIndex = Number(candidateWindow.style.zIndex) || 10;
        return candidateZIndex > topZIndex ? candidateWindow : topWindow;
      });
      focusFinderWindow(topFinderWindow);
      return true;
    }

    function getConnectedFinderOwnedWindows() {
      return [...document.querySelectorAll('.finder-window')].filter((finderWindow) => (
        isFinderOwnedWindow(finderWindow) && finderWindow.isConnected
      ));
    }

    function syncDockRunningIndicators() {
      // Finder is always running on Mac OS X Tiger, so its Dock
      // running indicator is always shown, even with no windows open.
      finderDockItem.classList.add('is-running');
      const safariWindow = document.getElementById('safari-window');
      const safariIsRunning = Boolean(safariWindow && safariWindow.isConnected);
      safariDockItem.classList.toggle('is-running', safariIsRunning);
      const textEditWindow = document.getElementById('textedit-window');
      const textEditIsRunning = Boolean(textEditWindow && textEditWindow.isConnected);
      textEditDockItem.classList.toggle('is-running', textEditIsRunning);
      const calculatorWindow = document.getElementById('calculator-window');
      const calculatorIsRunning = Boolean(calculatorWindow && calculatorWindow.isConnected);
      calculatorDockItem.classList.toggle('is-running', calculatorIsRunning);
      const iTunesWindow = document.getElementById('itunes-window');
      const iTunesIsRunning = Boolean(iTunesWindow && iTunesWindow.isConnected);
      iTunesDockItem.classList.toggle('is-running', iTunesIsRunning);
      const pagesWindow = document.getElementById('pages-window');
      const pagesIsRunning = Boolean(pagesWindow && pagesWindow.isConnected);
      pagesDockItem.classList.toggle('is-running', pagesIsRunning);
      const keynoteWindow = document.getElementById('keynote-window');
      const keynoteIsRunning = Boolean(keynoteWindow && keynoteWindow.isConnected);
      keynoteDockItem.classList.toggle('is-running', keynoteIsRunning);
      const numbersWindow = document.getElementById('numbers-window');
      const numbersIsRunning = Boolean(numbersWindow && numbersWindow.isConnected);
      numbersDockItem.classList.toggle('is-running', numbersIsRunning);
      const iPhotoWindow = document.getElementById('iphoto-window');
      const iPhotoIsRunning = Boolean(iPhotoWindow && iPhotoWindow.isConnected);
      iPhotoDockItem.classList.toggle('is-running', iPhotoIsRunning);
      const iMovieWindow = document.getElementById('imovie-window');
      const iMovieIsRunning = Boolean(iMovieWindow && iMovieWindow.isConnected);
      iMovieDockItem.classList.toggle('is-running', iMovieIsRunning);
      const garageBandWindow = document.getElementById('garageband-window');
      const garageBandIsRunning = Boolean(garageBandWindow && garageBandWindow.isConnected);
      garageBandDockItem.classList.toggle('is-running', garageBandIsRunning);
      const iDVDWindow = document.getElementById('idvd-window');
      const iDVDIsRunning = Boolean(iDVDWindow && iDVDWindow.isConnected);
      iDVDDockItem.classList.toggle('is-running', iDVDIsRunning);
      const sysPrefsWindow = document.getElementById('system-preferences-window');
      const sysPrefsIsRunning = Boolean(sysPrefsWindow && sysPrefsWindow.isConnected);
      sysPrefsDockItem.classList.toggle('is-running', sysPrefsIsRunning);
      dashboardDockItem.classList.toggle('is-running', isDashboardOpen());
      exposeDockItem.classList.toggle('is-running', isExposeActive);
    }

    function closeDockContextMenus() {
      finderDockContextMenu.hidden = true;
      safariDockContextMenu.hidden = true;
      textEditDockContextMenu.hidden = true;
      calculatorDockContextMenu.hidden = true;
      iTunesDockContextMenu.hidden = true;
      pagesDockContextMenu.hidden = true;
      keynoteDockContextMenu.hidden = true;
      numbersDockContextMenu.hidden = true;
      iPhotoDockContextMenu.hidden = true;
      iMovieDockContextMenu.hidden = true;
      garageBandDockContextMenu.hidden = true;
      iDVDDockContextMenu.hidden = true;
      desktopContextMenu.hidden = true;
    }

    function positionDockContextMenu(menu, dockItem) {
      const dockBounds = dockItem.getBoundingClientRect();
      menu.style.left = `${Math.round(dockBounds.left + (dockBounds.width / 2) - 84)}px`;
      menu.style.bottom = `${Math.round(window.innerHeight - dockBounds.top + 6)}px`;
      menu.style.top = 'auto';
    }

    function setDockContextMenuItemAvailable(menuItem, isAvailable) {
      menuItem.disabled = !isAvailable;
      menuItem.setAttribute('aria-disabled', String(!isAvailable));
    }

    function syncFinderDockContextMenuAvailability() {
      const finderOwnedWindows = getConnectedFinderOwnedWindows();
      const hasFinderWindows = finderOwnedWindows.length > 0;
      const hasVisibleFinderWindows = finderOwnedWindows.some((finderWindow) => (
        !finderWindow.classList.contains('is-minimized')
      ));
      setDockContextMenuItemAvailable(finderDockShowAllWindowsMenuItem, hasFinderWindows);
      setDockContextMenuItemAvailable(finderDockHideMenuItem, hasVisibleFinderWindows);
      setDockContextMenuItemAvailable(finderDockQuitMenuItem, hasFinderWindows);
    }

    function syncSafariDockContextMenuAvailability() {
      const safariWindow = document.getElementById('safari-window');
      const safariIsRunning = Boolean(safariWindow && safariWindow.isConnected);
      const safariIsVisible = safariIsRunning && !safariWindow.classList.contains('is-minimized');
      setDockContextMenuItemAvailable(safariDockShowAllWindowsMenuItem, safariIsRunning);
      setDockContextMenuItemAvailable(safariDockHideMenuItem, safariIsVisible);
      setDockContextMenuItemAvailable(safariDockQuitMenuItem, safariIsRunning);
    }

    function openFinderDockContextMenu(event) {
      event.preventDefault();
      event.stopPropagation();
      closeAllMenuDropdowns();
      syncFinderDockContextMenuAvailability();
      positionDockContextMenu(finderDockContextMenu, finderDockItem);
      finderDockContextMenu.hidden = false;
    }

    function openSafariDockContextMenu(event) {
      event.preventDefault();
      event.stopPropagation();
      closeAllMenuDropdowns();
      syncSafariDockContextMenuAvailability();
      positionDockContextMenu(safariDockContextMenu, safariDockItem);
      safariDockContextMenu.hidden = false;
    }

    function showAllFinderWindows() {
      const finderOwnedWindows = getConnectedFinderOwnedWindows();
      if (finderOwnedWindows.length === 0) {
        return;
      }
      finderOwnedWindows.forEach((finderWindow) => {
        finderWindow.classList.remove('is-minimized');
        finderWindow.removeAttribute('aria-hidden');
        finderWindow.removeAttribute('data-hidden-by-finder');
      });
      const topFinderWindow = finderOwnedWindows.reduce((topWindow, candidateWindow) => {
        const topZIndex = Number(topWindow.style.zIndex) || 10;
        const candidateZIndex = Number(candidateWindow.style.zIndex) || 10;
        return candidateZIndex > topZIndex ? candidateWindow : topWindow;
      });
      focusFinderWindow(topFinderWindow);
    }

    function activateFinderDockNewWindowMenuItem() {
      closeAllMenuDropdowns();
      openPreferredNewFinderWindow();
    }

    function activateFinderDockShowAllWindowsMenuItem() {
      if (getConnectedFinderOwnedWindows().length === 0) {
        return;
      }
      closeAllMenuDropdowns();
      showAllFinderWindows();
    }

    function activateFinderDockHideMenuItem() {
      const hasVisibleFinderWindows = getConnectedFinderOwnedWindows().some((finderWindow) => (
        !finderWindow.classList.contains('is-minimized')
      ));
      if (!hasVisibleFinderWindows) {
        return;
      }
      closeAllMenuDropdowns();
      hideFinderWindows();
    }

    function activateFinderDockQuitMenuItem() {
      if (getConnectedFinderOwnedWindows().length === 0) {
        return;
      }
      closeAllMenuDropdowns();
      quitFinderWindows();
    }

    function activateSafariDockShowAllWindowsMenuItem() {
      const safariWindow = document.getElementById('safari-window');
      if (!safariWindow || !safariWindow.isConnected) {
        return;
      }
      closeAllMenuDropdowns();
      focusFinderWindow(safariWindow);
    }

    function activateSafariDockHideMenuItem() {
      const safariWindow = document.getElementById('safari-window');
      if (!safariWindow || !safariWindow.isConnected || safariWindow.classList.contains('is-minimized')) {
        return;
      }
      closeAllMenuDropdowns();
      minimizeFinderWindow(safariWindow);
    }

    function activateSafariDockQuitMenuItem() {
      const safariWindow = document.getElementById('safari-window');
      if (!safariWindow || !safariWindow.isConnected) {
        return;
      }
      closeAllMenuDropdowns();
      closeFinderWindow(safariWindow);
    }

    function activateFinderFromDock() {
      const finderOwnedWindows = getConnectedFinderOwnedWindows();
      if (finderOwnedWindows.length > 0) {
        const topFinderWindow = finderOwnedWindows.reduce((topWindow, candidateWindow) => {
          const topZIndex = Number(topWindow.style.zIndex) || 10;
          const candidateZIndex = Number(candidateWindow.style.zIndex) || 10;
          return candidateZIndex > topZIndex ? candidateWindow : topWindow;
        });
        focusFinderWindow(topFinderWindow);
        return;
      }
      openPreferredNewFinderWindow();
    }

    function compactSimulatedWindowZIndexes() {
      const windows = [...document.querySelectorAll('.finder-window')].filter((simulatedWindow) => (
        simulatedWindow.isConnected
      ));
      windows.sort((leftWindow, rightWindow) => (
        (Number(leftWindow.style.zIndex) || 10) - (Number(rightWindow.style.zIndex) || 10)
      ));
      windows.forEach((simulatedWindow, windowIndex) => {
        simulatedWindow.style.zIndex = String(10 + windowIndex);
      });
      topWindowZIndex = 10 + windows.length;
    }

    function raiseSimulatedWindow(finderWindow) {
      topWindowZIndex += 1;
      if (topWindowZIndex > 900) {
        compactSimulatedWindowZIndexes();
        topWindowZIndex += 1;
      }
      finderWindow.style.zIndex = String(topWindowZIndex);
    }

    function focusFinderWindow(finderWindow) {
      if (!finderWindow.isConnected) {
        return;
      }

      if (isFinderOwnedWindow(finderWindow)) {
        revealFinderWindowsHiddenByFinder();
      }

      finderWindow.classList.remove('is-minimized');
      finderWindow.removeAttribute('aria-hidden');
      finderWindow.removeAttribute('data-hidden-by-finder');

      document.querySelectorAll('.finder-window').forEach((visibleWindow) => {
        visibleWindow.classList.remove('is-active');
      });

      raiseSimulatedWindow(finderWindow);
      finderWindow.classList.add('is-active');
      syncDockRunningIndicators();
      setActiveApplicationMenus(getApplicationMenuNameForWindow(finderWindow));
    }

    function getVisibleFinderWindows() {
      return [...document.querySelectorAll('.finder-window:not(.is-minimized)')];
    }

    function adoptExistingFinderWindow(existingWindow) {
      if (!existingWindow || !existingWindow.isConnected) {
        return false;
      }
      if (existingWindow.classList.contains('is-minimized')) {
        focusFinderWindow(existingWindow);
      }
      return true;
    }

    function minimizeFinderWindow(finderWindow) {
      if (!finderWindow || !finderWindow.isConnected) {
        return;
      }
      if (finderWindow.classList.contains('is-minimized')) {
        return;
      }

      const wasActive = finderWindow.classList.contains('is-active');
      finderWindow.classList.add('is-minimized');
      finderWindow.classList.remove('is-active');
      finderWindow.setAttribute('aria-hidden', 'true');

      if (!wasActive) {
        return;
      }

      const remainingWindows = getVisibleFinderWindows();
      if (remainingWindows.length === 0) {
        return;
      }

      const topRemainingWindow = remainingWindows.reduce((topWindow, candidateWindow) => {
        const topZIndex = Number(topWindow.style.zIndex) || 10;
        const candidateZIndex = Number(candidateWindow.style.zIndex) || 10;
        return candidateZIndex > topZIndex ? candidateWindow : topWindow;
      });
      focusFinderWindow(topRemainingWindow);
    }

    function activateMinimizeMenuItem() {
      const activeWindow = document.querySelector('.finder-window.is-active');
      closeAllMenuDropdowns();
      if (!activeWindow) {
        return;
      }
      minimizeFinderWindow(activeWindow);
    }

    function snapshotFinderWindowGeometry(finderWindow) {
      return {
        left: finderWindow.style.left,
        top: finderWindow.style.top,
        width: finderWindow.style.width,
        height: finderWindow.style.height,
        transform: finderWindow.style.transform
      };
    }

    function applyFinderWindowGeometry(finderWindow, geometry) {
      finderWindow.style.left = geometry.left;
      finderWindow.style.top = geometry.top;
      finderWindow.style.width = geometry.width;
      finderWindow.style.height = geometry.height;
      finderWindow.style.transform = geometry.transform;
    }

    function getSimulatedZoomedWindowBounds() {
      const menuBarHeight = 22;
      const edgeInset = 8;
      const dockReserve = 88;
      return {
        left: edgeInset,
        top: menuBarHeight + edgeInset,
        width: Math.max(320, window.innerWidth - edgeInset * 2),
        height: Math.max(180, window.innerHeight - menuBarHeight - dockReserve - edgeInset)
      };
    }

    function zoomFinderWindow(finderWindow) {
      if (!finderWindow || !finderWindow.isConnected) {
        return;
      }
      if (finderWindow.classList.contains('is-minimized')) {
        return;
      }

      if (finderWindow.classList.contains('is-zoomed')) {
        const previousGeometry = finderWindowZoomState.get(finderWindow);
        if (previousGeometry) {
          applyFinderWindowGeometry(finderWindow, previousGeometry);
        }
        finderWindow.classList.remove('is-zoomed');
        finderWindowZoomState.delete(finderWindow);
        return;
      }

      finderWindowZoomState.set(
        finderWindow,
        snapshotFinderWindowGeometry(finderWindow)
      );
      const zoomedBounds = getSimulatedZoomedWindowBounds();
      finderWindow.style.left = `${zoomedBounds.left}px`;
      finderWindow.style.top = `${zoomedBounds.top}px`;
      finderWindow.style.width = `${zoomedBounds.width}px`;
      finderWindow.style.height = `${zoomedBounds.height}px`;
      finderWindow.style.transform = 'none';
      finderWindow.classList.add('is-zoomed');
    }

    function activateZoomMenuItem() {
      const activeWindow = document.querySelector('.finder-window.is-active');
      closeAllMenuDropdowns();
      if (!activeWindow) {
        return;
      }
      zoomFinderWindow(activeWindow);
    }

    function bringAllFinderWindowsToFront() {
      const visibleWindows = getVisibleFinderWindows();
      if (visibleWindows.length === 0) {
        return;
      }

      const activeWindow = document.querySelector('.finder-window.is-active');
      const orderedWindows = visibleWindows.slice().sort((leftWindow, rightWindow) => {
        const leftZIndex = Number(leftWindow.style.zIndex) || 10;
        const rightZIndex = Number(rightWindow.style.zIndex) || 10;
        return leftZIndex - rightZIndex;
      });

      if (activeWindow && orderedWindows.includes(activeWindow)) {
        orderedWindows.splice(orderedWindows.indexOf(activeWindow), 1);
        orderedWindows.push(activeWindow);
      }

      orderedWindows.forEach((finderWindow) => {
        raiseSimulatedWindow(finderWindow);
      });

      if (
        activeWindow &&
        activeWindow.isConnected &&
        !activeWindow.classList.contains('is-minimized')
      ) {
        document.querySelectorAll('.finder-window').forEach((visibleWindow) => {
          visibleWindow.classList.remove('is-active');
        });
        activeWindow.classList.add('is-active');
      }
    }

    function activateBringAllToFrontMenuItem() {
      closeAllMenuDropdowns();
      bringAllFinderWindowsToFront();
    }

    function activateArrangeInFrontMenuItem() {
      const activeWindow = document.querySelector('.finder-window.is-active');
      closeAllMenuDropdowns();
      if (!activeWindow) {
        return;
      }
      focusFinderWindow(activeWindow);
    }

    function ensureFinderWindowTrafficLights(finderWindow) {
      const titleBar = finderWindow.querySelector('.finder-title-bar');
      if (!titleBar || titleBar.querySelector('.finder-minimize')) {
        return;
      }
      const closeButton = titleBar.querySelector('.finder-close');
      const minimizeButton = document.createElement('button');
      minimizeButton.type = 'button';
      minimizeButton.className = 'finder-minimize';
      minimizeButton.setAttribute('aria-label', 'Minimize');
      const zoomButton = document.createElement('button');
      zoomButton.type = 'button';
      zoomButton.className = 'finder-zoom';
      zoomButton.setAttribute('aria-label', 'Zoom');
      minimizeButton.addEventListener('click', (event) => {
        event.stopPropagation();
        minimizeFinderWindow(finderWindow);
      });
      zoomButton.addEventListener('click', (event) => {
        event.stopPropagation();
        zoomFinderWindow(finderWindow);
      });
      if (closeButton) {
        closeButton.after(minimizeButton);
        minimizeButton.after(zoomButton);
      } else {
        titleBar.prepend(minimizeButton, zoomButton);
      }
    }

    function enableWindowFocus(finderWindow) {
      ensureFinderWindowTrafficLights(finderWindow);
      finderWindow.addEventListener('pointerdown', () => {
        focusFinderWindow(finderWindow);
      });
      focusFinderWindow(finderWindow);
    }

    function closeFinderWindow(finderWindow) {
      const wasActive = finderWindow.classList.contains('is-active');
      const viewOptionsOwnerFinderWindow = viewOptionsOwnerFinderWindows.get(
        finderWindow
      );
      const getInfoFileSystemObject = getInfoFileSystemObjectsByWindow.get(
        finderWindow
      );
      const getInfoOwnerFinderWindow = getInfoOwnerFinderWindows.get(finderWindow);
      const dynamicFolderFileSystemObject =
        dynamicFolderFileSystemObjectsByWindow.get(finderWindow);
      const ownerFinderWindow =
        viewOptionsOwnerFinderWindow || getInfoOwnerFinderWindow;

      if (viewOptionsOwnerFinderWindow) {
        viewOptionsOwnerFinderWindows.delete(finderWindow);
        viewOptionsWindowsByFinderWindow.delete(viewOptionsOwnerFinderWindow);
      }
      if (getInfoFileSystemObject) {
        getInfoFileSystemObjectsByWindow.delete(finderWindow);
        getInfoWindowsByFileSystemObject.delete(getInfoFileSystemObject);
        getInfoOwnerFinderWindows.delete(finderWindow);
      }
      if (dynamicFolderFileSystemObject) {
        dynamicFolderFileSystemObjectsByWindow.delete(finderWindow);
        dynamicFolderWindowsByFileSystemObject.delete(
          dynamicFolderFileSystemObject
        );
      }
      finderWindow.remove();
      syncDockRunningIndicators();
      if (finderWindow.getAttribute('data-textedit-window') === 'true') {
        textEditCurrentFileSystemObject = null;
      }
      if (finderWindow.getAttribute('data-calculator-window') === 'true') {
        resetCalculatorState();
      }
      if (finderWindow.getAttribute('data-itunes-window') === 'true') {
        stopITunesPlayback();
      }
      if (finderWindow.getAttribute('data-pages-window') === 'true') {
        pagesCurrentFileSystemObject = null;
      }
      if (finderWindow.getAttribute('data-keynote-window') === 'true') {
        commitKeynoteSlideEdits();
        resetKeynoteSessionState();
      }
      if (finderWindow.getAttribute('data-numbers-window') === 'true') {
        resetNumbersSessionState();
      }
      if (finderWindow.getAttribute('data-imovie-window') === 'true') {
        resetIMovieSessionState();
      }
      if (finderWindow.getAttribute('data-garageband-window') === 'true') {
        resetGarageBandSessionState();
      }
      if (finderWindow.getAttribute('data-idvd-window') === 'true') {
        resetIDVDSessionState();
      }

      if (!wasActive) {
        if (!document.querySelector('.finder-window.is-active')) {
          setActiveApplicationMenus('finder');
        }
        return;
      }

      if (ownerFinderWindow && ownerFinderWindow.isConnected) {
        focusFinderWindow(ownerFinderWindow);
        return;
      }

      const remainingWindows = getVisibleFinderWindows();
      if (remainingWindows.length === 0) {
        setActiveApplicationMenus('finder');
        return;
      }

      const topRemainingWindow = remainingWindows.reduce((topWindow, candidateWindow) => {
        const topZIndex = Number(topWindow.style.zIndex) || 10;
        const candidateZIndex = Number(candidateWindow.style.zIndex) || 10;
        return candidateZIndex > topZIndex ? candidateWindow : topWindow;
      });
      focusFinderWindow(topRemainingWindow);
    }

    function makeWindowDraggable(finderWindow, titleBar) {
      let isDragging = false;
      let dragOffsetX = 0;
      let dragOffsetY = 0;

      titleBar.addEventListener('pointerdown', (event) => {
        if (event.button !== 0 || event.target.closest('.finder-close, .finder-minimize, .finder-zoom') || isExposeActive) {
          return;
        }

        const windowBounds = finderWindow.getBoundingClientRect();
        dragOffsetX = event.clientX - windowBounds.left;
        dragOffsetY = event.clientY - windowBounds.top;
        finderWindow.style.left = `${windowBounds.left}px`;
        finderWindow.style.top = `${windowBounds.top}px`;
        finderWindow.style.transform = 'none';
        isDragging = true;
        titleBar.setPointerCapture(event.pointerId);
        event.preventDefault();
      });

      titleBar.addEventListener('pointermove', (event) => {
        if (!isDragging) {
          return;
        }

        finderWindow.style.left = `${event.clientX - dragOffsetX}px`;
        finderWindow.style.top = `${event.clientY - dragOffsetY}px`;
      });

      function stopDragging(event) {
        if (!isDragging) {
          return;
        }

        isDragging = false;
        if (titleBar.hasPointerCapture(event.pointerId)) {
          titleBar.releasePointerCapture(event.pointerId);
        }
      }

      titleBar.addEventListener('pointerup', stopDragging);
      titleBar.addEventListener('pointercancel', stopDragging);
    }

    function createStaticViewOptionsControl(labelText, visualClassName, visualMarkup) {
      const control = document.createElement('div');
      control.className = 'view-options-static-control';
      control.setAttribute('aria-disabled', 'true');

      const label = document.createElement('span');
      label.className = 'view-options-control-label';
      label.textContent = labelText;

      const visual = document.createElement('span');
      visual.className = `view-options-control-visual ${visualClassName}`;
      visual.setAttribute('aria-hidden', 'true');
      visual.innerHTML = visualMarkup;

      control.append(label, visual);
      return control;
    }

    function createShowItemInfoViewOptionsControl(finderWindow) {
      const control = document.createElement('div');
      control.className = 'view-options-static-control view-options-item-info-row';

      const label = document.createElement('span');
      label.className = 'view-options-control-label';
      label.textContent = 'Show Item Info';

      const visual = document.createElement('div');
      visual.className = 'view-options-control-visual view-options-item-info-control';

      const checkbox = document.createElement('button');
      checkbox.type = 'button';
      checkbox.className = 'view-options-checkbox-display';
      checkbox.setAttribute('aria-label', 'Show Item Info');
      checkbox.setAttribute('aria-pressed', 'false');
      checkbox.addEventListener('click', (event) => {
        event.stopPropagation();
        applyFinderWindowShowItemInfo(
          finderWindow,
          !getFinderWindowShowItemInfo(finderWindow)
        );
      });

      visual.appendChild(checkbox);
      control.append(label, visual);
      return control;
    }

    function createShowIconPreviewViewOptionsControl(finderWindow) {
      const control = document.createElement('div');
      control.className = 'view-options-static-control view-options-icon-preview-row';

      const label = document.createElement('span');
      label.className = 'view-options-control-label';
      label.textContent = 'Show Icon Preview';

      const visual = document.createElement('div');
      visual.className = 'view-options-control-visual view-options-icon-preview-control';

      const checkbox = document.createElement('button');
      checkbox.type = 'button';
      checkbox.className = 'view-options-checkbox-display';
      checkbox.setAttribute('aria-label', 'Show Icon Preview');
      checkbox.setAttribute('aria-pressed', 'false');
      checkbox.addEventListener('click', (event) => {
        event.stopPropagation();
        applyFinderWindowShowIconPreview(
          finderWindow,
          !getFinderWindowShowIconPreview(finderWindow)
        );
      });

      visual.appendChild(checkbox);
      control.append(label, visual);
      return control;
    }

    function createLabelPositionViewOptionsControl(finderWindow) {
      const control = document.createElement('div');
      control.className = 'view-options-static-control view-options-label-position-row';

      const label = document.createElement('span');
      label.className = 'view-options-control-label';
      label.textContent = 'Label Position';

      const visual = document.createElement('div');
      visual.className = 'view-options-control-visual view-options-label-position-control';

      const display = document.createElement('div');
      display.className = 'view-options-label-position-display';
      display.setAttribute('role', 'group');
      display.setAttribute('aria-label', 'Label Position');

      const positionLabels = {
        bottom: 'Labels on bottom',
        right: 'Labels on right'
      };
      simulatedLabelPositions.forEach((position) => {
        const choice = document.createElement('button');
        choice.type = 'button';
        choice.className = 'view-options-label-position-choice';
        choice.setAttribute('data-label-position', position);
        choice.setAttribute('aria-label', positionLabels[position]);
        choice.setAttribute('aria-pressed', 'false');
        choice.addEventListener('click', (event) => {
          event.stopPropagation();
          applyFinderWindowLabelPosition(finderWindow, position);
        });
        display.appendChild(choice);
      });

      visual.appendChild(display);
      control.append(label, visual);
      return control;
    }

    function createTextSizeViewOptionsControl(finderWindow) {
      const control = document.createElement('div');
      control.className = 'view-options-static-control view-options-text-size-row';

      const label = document.createElement('span');
      label.className = 'view-options-control-label';
      label.textContent = 'Text Size';

      const visual = document.createElement('div');
      visual.className = 'view-options-control-visual view-options-text-size-control';

      const display = document.createElement('button');
      display.type = 'button';
      display.className = 'view-options-text-size-display';
      display.setAttribute('aria-haspopup', 'listbox');
      display.setAttribute('aria-expanded', 'false');
      display.setAttribute('aria-label', 'Text Size');

      const value = document.createElement('span');
      value.className = 'view-options-text-size-value';

      const steppers = document.createElement('span');
      steppers.className = 'view-options-text-size-steppers';

      const largerButton = document.createElement('button');
      largerButton.type = 'button';
      largerButton.className = 'view-options-text-size-step';
      largerButton.setAttribute('data-text-size-step', 'up');
      largerButton.setAttribute('aria-label', 'Larger text');
      largerButton.textContent = '▴';

      const smallerButton = document.createElement('button');
      smallerButton.type = 'button';
      smallerButton.className = 'view-options-text-size-step';
      smallerButton.setAttribute('data-text-size-step', 'down');
      smallerButton.setAttribute('aria-label', 'Smaller text');
      smallerButton.textContent = '▾';

      const menu = document.createElement('div');
      menu.className = 'view-options-text-size-menu';
      menu.hidden = true;
      menu.setAttribute('role', 'listbox');
      menu.setAttribute('aria-label', 'Text Size');

      function setMenuOpen(isOpen) {
        menu.hidden = !isOpen;
        display.setAttribute('aria-expanded', String(isOpen));
      }

      function stepTextSize(direction) {
        const currentTextSize = getFinderWindowTextSize(finderWindow);
        const currentIndex = simulatedTextSizes.indexOf(currentTextSize);
        const nextIndex = Math.max(
          0,
          Math.min(simulatedTextSizes.length - 1, currentIndex + direction)
        );
        applyFinderWindowTextSize(finderWindow, simulatedTextSizes[nextIndex]);
      }

      simulatedTextSizes.forEach((textSize) => {
        const choice = document.createElement('button');
        choice.type = 'button';
        choice.className = 'view-options-text-size-choice';
        choice.setAttribute('role', 'option');
        choice.setAttribute('data-text-size', String(textSize));
        choice.textContent = String(textSize);
        choice.addEventListener('click', (event) => {
          event.stopPropagation();
          applyFinderWindowTextSize(finderWindow, textSize);
          setMenuOpen(false);
        });
        menu.appendChild(choice);
      });

      display.addEventListener('click', (event) => {
        event.stopPropagation();
        setMenuOpen(menu.hidden);
      });
      largerButton.addEventListener('click', (event) => {
        event.stopPropagation();
        setMenuOpen(false);
        stepTextSize(1);
      });
      smallerButton.addEventListener('click', (event) => {
        event.stopPropagation();
        setMenuOpen(false);
        stepTextSize(-1);
      });

      steppers.append(largerButton, smallerButton);
      display.appendChild(value);
      visual.append(display, steppers, menu);
      control.append(label, visual);
      return control;
    }

    function createIconSizeViewOptionsControl(finderWindow) {
      const control = document.createElement('div');
      control.className = 'view-options-static-control view-options-icon-size-row';

      const label = document.createElement('span');
      label.className = 'view-options-control-label';
      label.textContent = 'Icon Size';

      const visual = document.createElement('div');
      visual.className = 'view-options-control-visual view-options-icon-size-control';

      const track = document.createElement('div');
      track.className = 'view-options-slider-track is-interactive';
      track.setAttribute('role', 'group');
      track.setAttribute('aria-label', 'Icon Size');

      const sizeLabels = {
        32: 'Small icons',
        48: 'Medium-small icons',
        64: 'Medium icons',
        80: 'Large icons'
      };
      simulatedIconSizes.forEach((iconSize) => {
        const choice = document.createElement('button');
        choice.type = 'button';
        choice.className = 'view-options-icon-size-choice';
        choice.setAttribute('data-icon-size', String(iconSize));
        choice.setAttribute('aria-label', sizeLabels[iconSize]);
        choice.setAttribute('aria-pressed', 'false');
        choice.addEventListener('click', (event) => {
          event.stopPropagation();
          applyFinderWindowIconSize(finderWindow, iconSize);
        });
        track.appendChild(choice);
      });

      const thumb = document.createElement('span');
      thumb.className = 'view-options-slider-thumb';
      thumb.setAttribute('aria-hidden', 'true');
      track.appendChild(thumb);
      visual.appendChild(track);
      control.append(label, visual);
      return control;
    }

    function showViewOptionsWindow(finderWindow) {
      const existingViewOptionsWindow = viewOptionsWindowsByFinderWindow.get(finderWindow);
      if (existingViewOptionsWindow && existingViewOptionsWindow.isConnected) {
        focusFinderWindow(existingViewOptionsWindow);
        return;
      }

      if (existingViewOptionsWindow) {
        viewOptionsWindowsByFinderWindow.delete(finderWindow);
      }

      viewOptionsWindowSequence += 1;
      const viewOptionsWindow = document.createElement('section');
      viewOptionsWindow.id = `view-options-window-${viewOptionsWindowSequence}`;
      viewOptionsWindow.className = 'finder-window view-options-window';
      viewOptionsWindow.setAttribute('role', 'dialog');
      viewOptionsWindow.setAttribute(
        'aria-labelledby',
        `view-options-window-title-${viewOptionsWindowSequence}`
      );
      viewOptionsWindow.setAttribute('data-view-options-window', 'true');
      viewOptionsWindow.setAttribute('data-view-options-for', finderWindow.id);

      const titleBar = document.createElement('div');
      titleBar.className = 'finder-title-bar';

      const closeButton = document.createElement('button');
      closeButton.type = 'button';
      closeButton.className = 'finder-close';
      closeButton.setAttribute('aria-label', 'Close');
      closeButton.addEventListener('click', () => {
        closeFinderWindow(viewOptionsWindow);
      });

      const title = document.createElement('div');
      title.id = `view-options-window-title-${viewOptionsWindowSequence}`;
      title.className = 'finder-title';
      title.textContent = 'View Options';

      const content = document.createElement('div');
      content.className = 'finder-content view-options-content';
      content.setAttribute('aria-label', 'View Options controls');
      content.append(
        createIconSizeViewOptionsControl(finderWindow),
        createTextSizeViewOptionsControl(finderWindow),
        createLabelPositionViewOptionsControl(finderWindow),
        createShowItemInfoViewOptionsControl(finderWindow),
        createShowIconPreviewViewOptionsControl(finderWindow)
      );

      titleBar.append(closeButton, title);
      viewOptionsWindow.append(titleBar, content);
      viewOptionsWindowsByFinderWindow.set(finderWindow, viewOptionsWindow);
      viewOptionsOwnerFinderWindows.set(viewOptionsWindow, finderWindow);
      document.body.appendChild(viewOptionsWindow);
      enableWindowFocus(viewOptionsWindow);
      makeWindowDraggable(viewOptionsWindow, titleBar);
      syncViewOptionsIconSizeControl(finderWindow);
      syncViewOptionsTextSizeControl(finderWindow);
      syncViewOptionsLabelPositionControl(finderWindow);
      syncViewOptionsShowItemInfoControl(finderWindow);
      syncViewOptionsShowIconPreviewControl(finderWindow);
    }

    function getFileSystemObjectKind(fileSystemObject) {
      const kindByType = {
        application: 'Application',
        drive: 'Volume',
        file: 'Plain Text Document',
        folder: 'Folder'
      };
      return kindByType[fileSystemObject.type] || 'Filesystem Item';
    }

    function findParentFileSystemObject(fileSystemObject, directoryFileSystemObject) {
      const children = getFileSystemObjectChildren(directoryFileSystemObject);
      for (const childFileSystemObject of children) {
        if (childFileSystemObject === fileSystemObject) {
          return directoryFileSystemObject;
        }
        if (childFileSystemObject.children) {
          const nestedParent = findParentFileSystemObject(
            fileSystemObject,
            childFileSystemObject
          );
          if (nestedParent) {
            return nestedParent;
          }
        }
      }
      return null;
    }

    function getFileSystemObjectLocation(fileSystemObject) {
      if (
        fileSystemObject === virtualFileSystem.root ||
        fileSystemObject === virtualDesktopEnvironment.trash
      ) {
        return 'Desktop';
      }

      const parentFileSystemObject =
        findParentFileSystemObject(fileSystemObject, virtualFileSystem.root) ||
        findParentFileSystemObject(fileSystemObject, virtualDesktopEnvironment.trash);
      return parentFileSystemObject ? parentFileSystemObject.name : 'Virtual Desktop';
    }

    function getEnclosingFolderFileSystemObject(fileSystemObject) {
      if (
        !fileSystemObject ||
        fileSystemObject === virtualFileSystem.root
      ) {
        return null;
      }

      return findParentFileSystemObject(
        fileSystemObject,
        virtualFileSystem.root
      ) || findParentFileSystemObject(
        fileSystemObject,
        virtualDesktopEnvironment.trash
      );
    }

    function getFinderWindowSingletonId(directoryFileSystemObject) {
      if (directoryFileSystemObject === virtualFileSystem.root) {
        return 'macintosh-hd-window';
      }
      if (directoryFileSystemObject === applicationsFileSystemObject) {
        return 'applications-window';
      }
      if (directoryFileSystemObject === documentsFileSystemObject) {
        return 'documents-window';
      }
      if (directoryFileSystemObject === virtualDesktopEnvironment.trash) {
        return 'trash-window';
      }
      return null;
    }

    function releaseFinderWindowDirectoryIdentity(
      finderWindow,
      directoryFileSystemObject
    ) {
      if (
        dynamicFolderFileSystemObjectsByWindow.get(finderWindow) ===
        directoryFileSystemObject
      ) {
        dynamicFolderFileSystemObjectsByWindow.delete(finderWindow);
        if (
          dynamicFolderWindowsByFileSystemObject.get(
            directoryFileSystemObject
          ) === finderWindow
        ) {
          dynamicFolderWindowsByFileSystemObject.delete(
            directoryFileSystemObject
          );
        }
      }

      const singletonId = getFinderWindowSingletonId(directoryFileSystemObject);
      if (singletonId && finderWindow.id === singletonId) {
        finderWindow.removeAttribute('id');
      }
    }

    function associateFinderWindowWithDirectory(
      finderWindow,
      directoryFileSystemObject
    ) {
      finderWindowFileSystemObjects.set(finderWindow, directoryFileSystemObject);

      if (
        !directoryFileSystemObject ||
        directoryFileSystemObject.type !== 'folder' ||
        getFinderWindowSingletonId(directoryFileSystemObject)
      ) {
        return;
      }

      const existingFolderWindow = dynamicFolderWindowsByFileSystemObject.get(
        directoryFileSystemObject
      );
      if (existingFolderWindow && existingFolderWindow.isConnected) {
        return;
      }

      dynamicFolderWindowsByFileSystemObject.set(
        directoryFileSystemObject,
        finderWindow
      );
      dynamicFolderFileSystemObjectsByWindow.set(
        finderWindow,
        directoryFileSystemObject
      );
    }

    function getFinderWindowNavigationSelection(finderWindow) {
      const selectedDirectFileSystemObjects =
        getSelectedDirectFinderFileSystemObjects(finderWindow);
      if (selectedDirectFileSystemObjects.length > 0) {
        return selectedDirectFileSystemObjects;
      }

      const selectedFileSystemObject = getSelectedFinderFileSystemObject(
        finderWindow
      );
      return selectedFileSystemObject ? [selectedFileSystemObject] : [];
    }

    function snapshotFinderWindowNavigation(finderWindow) {
      return Object.freeze({
        directoryFileSystemObject: finderWindowFileSystemObjects.get(
          finderWindow
        ),
        selectedFileSystemObjects: Object.freeze([
          ...getFinderWindowNavigationSelection(finderWindow)
        ])
      });
    }

    function recordFinderWindowNavigation(finderWindow) {
      const navigationSnapshot = snapshotFinderWindowNavigation(finderWindow);
      if (!navigationSnapshot.directoryFileSystemObject) {
        return;
      }

      let backHistory = finderWindowBackHistory.get(finderWindow);
      if (!backHistory) {
        backHistory = [];
        finderWindowBackHistory.set(finderWindow, backHistory);
      }
      backHistory.push(navigationSnapshot);

      const forwardHistory = finderWindowForwardHistory.get(finderWindow);
      if (forwardHistory) {
        forwardHistory.length = 0;
      }
    }

    function restoreFinderWindowSelection(finderWindow, selectedFileSystemObjects) {
      const finderContent = finderWindow.querySelector('.finder-content');
      if (
        !finderContent ||
        !selectedFileSystemObjects ||
        selectedFileSystemObjects.length === 0
      ) {
        return;
      }

      const selectedFileSystemObjectSet = new Set(selectedFileSystemObjects);
      const finderItems = getDirectFinderItems(finderContent);
      const matchingFinderItems = finderItems.filter((finderItem) => (
        selectedFileSystemObjectSet.has(finderItemFileSystemObjects.get(finderItem))
      ));
      if (matchingFinderItems.length === 0) {
        return;
      }

      if (matchingFinderItems.length === 1) {
        selectFinderFileSystemObject(
          finderWindow,
          finderItemFileSystemObjects.get(matchingFinderItems[0])
        );
        return;
      }

      finderContent.setAttribute('aria-multiselectable', 'true');
      finderItems.forEach((finderItem) => {
        setFinderItemSelected(
          finderItem,
          selectedFileSystemObjectSet.has(
            finderItemFileSystemObjects.get(finderItem)
          )
        );
      });

      if (finderWindow.getAttribute('data-view-mode') !== 'columns') {
        return;
      }

      const directoryFileSystemObject = finderWindowFileSystemObjects.get(
        finderWindow
      );
      if (directoryFileSystemObject) {
        renderFinderColumns(
          finderWindow,
          finderContent,
          directoryFileSystemObject
        );
      }
    }

    function selectFinderFileSystemObject(finderWindow, fileSystemObject) {
      const finderContent = finderWindow.querySelector('.finder-content');
      if (!finderContent || !fileSystemObject) {
        return;
      }

      const selectedFinderItem = getDirectFinderItems(finderContent).find(
        (finderItem) => (
          finderItemFileSystemObjects.get(finderItem) === fileSystemObject
        )
      );
      if (!selectedFinderItem) {
        return;
      }

      selectDirectFinderItem(finderContent, selectedFinderItem);
      if (finderWindow.getAttribute('data-view-mode') !== 'columns') {
        return;
      }

      const directoryFileSystemObject = finderWindowFileSystemObjects.get(
        finderWindow
      );
      if (directoryFileSystemObject) {
        renderFinderColumns(
          finderWindow,
          finderContent,
          directoryFileSystemObject
        );
      }
    }

    function navigateFinderWindowToDirectory(
      finderWindow,
      directoryFileSystemObject,
      selectedFileSystemObject,
      navigationOptions
    ) {
      const currentFileSystemObject = finderWindowFileSystemObjects.get(
        finderWindow
      );
      if (
        !currentFileSystemObject ||
        !directoryFileSystemObject ||
        currentFileSystemObject === directoryFileSystemObject
      ) {
        return;
      }

      if (!navigationOptions || navigationOptions.recordHistory !== false) {
        recordFinderWindowNavigation(finderWindow);
      }

      releaseFinderWindowDirectoryIdentity(
        finderWindow,
        currentFileSystemObject
      );
      associateFinderWindowWithDirectory(
        finderWindow,
        directoryFileSystemObject
      );

      const title = finderWindow.querySelector('.finder-title');
      if (title) {
        title.textContent = directoryFileSystemObject.name;
      }

      const finderContent = finderWindow.querySelector('.finder-content');
      if (finderContent) {
        finderContent.setAttribute('aria-label', directoryFileSystemObject.name);
      }

      refreshFinderWindowContents(finderWindow);
      selectFinderFileSystemObject(finderWindow, selectedFileSystemObject);
      recordSimulatedRecentFolder(directoryFileSystemObject);
    }

    function activateBackMenuItem() {
      const activeFinderWindow = document.querySelector(
        '.finder-window.is-active[data-finder-window="true"]'
      );
      closeAllMenuDropdowns();
      if (!activeFinderWindow) {
        return;
      }

      const backHistory = finderWindowBackHistory.get(activeFinderWindow);
      if (!backHistory || backHistory.length === 0) {
        return;
      }

      const currentNavigationSnapshot = snapshotFinderWindowNavigation(
        activeFinderWindow
      );
      const previousNavigationSnapshot = backHistory.pop();
      if (
        !previousNavigationSnapshot.directoryFileSystemObject ||
        previousNavigationSnapshot.directoryFileSystemObject ===
          currentNavigationSnapshot.directoryFileSystemObject
      ) {
        backHistory.push(previousNavigationSnapshot);
        return;
      }

      let forwardHistory = finderWindowForwardHistory.get(activeFinderWindow);
      if (!forwardHistory) {
        forwardHistory = [];
        finderWindowForwardHistory.set(activeFinderWindow, forwardHistory);
      }
      forwardHistory.push(currentNavigationSnapshot);

      navigateFinderWindowToDirectory(
        activeFinderWindow,
        previousNavigationSnapshot.directoryFileSystemObject,
        null,
        { recordHistory: false }
      );
      restoreFinderWindowSelection(
        activeFinderWindow,
        previousNavigationSnapshot.selectedFileSystemObjects
      );
    }

    function activateForwardMenuItem() {
      const activeFinderWindow = document.querySelector(
        '.finder-window.is-active[data-finder-window="true"]'
      );
      closeAllMenuDropdowns();
      if (!activeFinderWindow) {
        return;
      }

      const forwardHistory = finderWindowForwardHistory.get(activeFinderWindow);
      if (!forwardHistory || forwardHistory.length === 0) {
        return;
      }

      const currentNavigationSnapshot = snapshotFinderWindowNavigation(
        activeFinderWindow
      );
      const nextNavigationSnapshot = forwardHistory.pop();
      if (
        !nextNavigationSnapshot.directoryFileSystemObject ||
        nextNavigationSnapshot.directoryFileSystemObject ===
          currentNavigationSnapshot.directoryFileSystemObject
      ) {
        forwardHistory.push(nextNavigationSnapshot);
        return;
      }

      let backHistory = finderWindowBackHistory.get(activeFinderWindow);
      if (!backHistory) {
        backHistory = [];
        finderWindowBackHistory.set(activeFinderWindow, backHistory);
      }
      backHistory.push(currentNavigationSnapshot);

      navigateFinderWindowToDirectory(
        activeFinderWindow,
        nextNavigationSnapshot.directoryFileSystemObject,
        null,
        { recordHistory: false }
      );
      restoreFinderWindowSelection(
        activeFinderWindow,
        nextNavigationSnapshot.selectedFileSystemObjects
      );
    }

    function activateHomeMenuItem() {
      const activeFinderWindow = document.querySelector(
        '.finder-window.is-active[data-finder-window="true"]'
      );
      closeAllMenuDropdowns();
      if (!activeFinderWindow || !homeFileSystemObject) {
        return;
      }

      navigateFinderWindowToDirectory(
        activeFinderWindow,
        homeFileSystemObject
      );
    }

    function activateComputerMenuItem() {
      const activeFinderWindow = document.querySelector(
        '.finder-window.is-active[data-finder-window="true"]'
      );
      closeAllMenuDropdowns();
      if (!activeFinderWindow || !computerFileSystemObject) {
        return;
      }

      navigateFinderWindowToDirectory(
        activeFinderWindow,
        computerFileSystemObject
      );
    }

    function activateIDiskMenuItem() {
      const activeFinderWindow = document.querySelector(
        '.finder-window.is-active[data-finder-window="true"]'
      );
      closeAllMenuDropdowns();
      if (!activeFinderWindow || !iDiskFileSystemObject) {
        return;
      }

      navigateFinderWindowToDirectory(
        activeFinderWindow,
        iDiskFileSystemObject
      );
    }

    function activateNetworkMenuItem() {
      const activeFinderWindow = document.querySelector(
        '.finder-window.is-active[data-finder-window="true"]'
      );
      closeAllMenuDropdowns();
      if (!activeFinderWindow || !networkFileSystemObject) {
        return;
      }

      navigateFinderWindowToDirectory(
        activeFinderWindow,
        networkFileSystemObject
      );
    }

    function activateApplicationsMenuItem() {
      const activeFinderWindow = document.querySelector(
        '.finder-window.is-active[data-finder-window="true"]'
      );
      closeAllMenuDropdowns();
      if (!activeFinderWindow || !applicationsFileSystemObject) {
        return;
      }

      navigateFinderWindowToDirectory(
        activeFinderWindow,
        applicationsFileSystemObject
      );
    }

    function activateUtilitiesMenuItem() {
      const activeFinderWindow = document.querySelector(
        '.finder-window.is-active[data-finder-window="true"]'
      );
      closeAllMenuDropdowns();
      if (!activeFinderWindow || !utilitiesFileSystemObject) {
        return;
      }

      navigateFinderWindowToDirectory(
        activeFinderWindow,
        utilitiesFileSystemObject
      );
    }

    function activateEnclosingFolderMenuItem() {
      const activeFinderWindow = document.querySelector(
        '.finder-window.is-active[data-finder-window="true"]'
      );
      closeAllMenuDropdowns();
      if (!activeFinderWindow) {
        return;
      }

      const currentFileSystemObject = finderWindowFileSystemObjects.get(
        activeFinderWindow
      );
      const enclosingFolderFileSystemObject = getEnclosingFolderFileSystemObject(
        currentFileSystemObject
      );
      if (!enclosingFolderFileSystemObject) {
        return;
      }

      navigateFinderWindowToDirectory(
        activeFinderWindow,
        enclosingFolderFileSystemObject,
        currentFileSystemObject
      );
    }

    function getSimulatedFileSystemObjectInformation(fileSystemObject) {
      if (fileSystemObject.type === 'folder') {
        const itemCount = getFileSystemObjectChildren(fileSystemObject).length;
        return `${itemCount} simulated ${itemCount === 1 ? 'item' : 'items'}`;
      }
      if (fileSystemObject.type === 'application') {
        return 'Read-only simulated application';
      }
      if (fileSystemObject.type === 'drive') {
        return 'Simulated startup volume';
      }
      return 'Read-only simulated document';
    }

    function appendGetInfoDetail(details, labelText, valueText) {
      const label = document.createElement('div');
      label.className = 'get-info-label';
      label.textContent = `${labelText}:`;

      const value = document.createElement('div');
      value.className = 'get-info-value';
      value.textContent = valueText;
      details.append(label, value);
    }

    function showGetInfoWindow(fileSystemObject, ownerFinderWindow) {
      const existingGetInfoWindow = getInfoWindowsByFileSystemObject.get(
        fileSystemObject
      );
      if (existingGetInfoWindow && existingGetInfoWindow.isConnected) {
        getInfoOwnerFinderWindows.set(existingGetInfoWindow, ownerFinderWindow);
        focusFinderWindow(existingGetInfoWindow);
        return;
      }

      if (existingGetInfoWindow) {
        getInfoWindowsByFileSystemObject.delete(fileSystemObject);
      }

      getInfoWindowSequence += 1;
      const getInfoWindow = document.createElement('section');
      getInfoWindow.id = `get-info-window-${getInfoWindowSequence}`;
      getInfoWindow.className = 'finder-window get-info-window';
      getInfoWindow.setAttribute('role', 'dialog');
      getInfoWindow.setAttribute(
        'aria-labelledby',
        `get-info-window-title-${getInfoWindowSequence}`
      );
      getInfoWindow.setAttribute('data-get-info-window', 'true');
      getInfoWindow.setAttribute('data-get-info-object-name', fileSystemObject.name);

      const titleBar = document.createElement('div');
      titleBar.className = 'finder-title-bar';

      const closeButton = document.createElement('button');
      closeButton.type = 'button';
      closeButton.className = 'finder-close';
      closeButton.setAttribute('aria-label', 'Close');
      closeButton.addEventListener('click', () => {
        closeFinderWindow(getInfoWindow);
      });

      const title = document.createElement('div');
      title.id = `get-info-window-title-${getInfoWindowSequence}`;
      title.className = 'finder-title';
      title.textContent = `${fileSystemObject.name} Info`;

      const content = document.createElement('div');
      content.className = 'finder-content get-info-content';
      content.setAttribute('aria-label', `${fileSystemObject.name} information`);

      const kind = getFileSystemObjectKind(fileSystemObject);
      const summary = document.createElement('div');
      summary.className = 'get-info-summary';

      const icon = document.createElement('div');
      icon.className = 'get-info-icon';
      icon.setAttribute('aria-hidden', 'true');
      icon.innerHTML = getColumnIconMarkup(fileSystemObject);

      const summaryText = document.createElement('div');
      summaryText.className = 'get-info-summary-text';

      const summaryName = document.createElement('div');
      summaryName.className = 'get-info-summary-name';
      summaryName.textContent = fileSystemObject.name;

      const summaryKind = document.createElement('div');
      summaryKind.className = 'get-info-summary-kind';
      summaryKind.textContent = kind;
      summaryText.append(summaryName, summaryKind);
      summary.append(icon, summaryText);

      const generalSection = document.createElement('div');
      generalSection.className = 'get-info-section';

      const generalHeading = document.createElement('div');
      generalHeading.className = 'get-info-section-heading';
      generalHeading.textContent = 'General';

      const details = document.createElement('div');
      details.className = 'get-info-details';
      appendGetInfoDetail(details, 'Name', fileSystemObject.name);
      appendGetInfoDetail(details, 'Kind', kind);
      appendGetInfoDetail(
        details,
        'Where',
        getFileSystemObjectLocation(fileSystemObject)
      );
      appendGetInfoDetail(
        details,
        'Information',
        getSimulatedFileSystemObjectInformation(fileSystemObject)
      );

      generalSection.append(generalHeading, details);
      content.append(summary, generalSection);
      titleBar.append(closeButton, title);
      getInfoWindow.append(titleBar, content);
      getInfoWindowsByFileSystemObject.set(fileSystemObject, getInfoWindow);
      getInfoFileSystemObjectsByWindow.set(getInfoWindow, fileSystemObject);
      getInfoOwnerFinderWindows.set(getInfoWindow, ownerFinderWindow);
      document.body.appendChild(getInfoWindow);
      enableWindowFocus(getInfoWindow);
      makeWindowDraggable(getInfoWindow, titleBar);
    }


    function createFinderSidebarIcon(kind) {
      if (kind === 'drive') {
        return '<svg viewBox="0 0 16 16" aria-hidden="true"><rect x="1.5" y="4" width="13" height="8.5" rx="1.6" fill="#d5d8dc" stroke="#6b7177"/><rect x="3" y="9.2" width="10" height="1.2" rx="0.5" fill="#8b9197"/><circle cx="12.1" cy="10.7" r="0.7" fill="#4ec92a"/></svg>';
      }
      if (kind === 'network') {
        return '<svg viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="5.4" fill="#7ec8ef" stroke="#2a6f9a"/><path d="M8 2.6v10.8M2.7 8h10.6M4.1 4.6c1.3 1 4 1.6 7.8 0M4.1 11.4c1.3-1 4-1.6 7.8 0" fill="none" stroke="#2f6284" stroke-width="0.8"/></svg>';
      }
      if (kind === 'desktop') {
        return '<svg viewBox="0 0 16 16" aria-hidden="true"><rect x="2" y="2.4" width="12" height="8.4" rx="1.2" fill="#7ec4ef" stroke="#2a6f9a"/><path d="M5 13.2h6M8 10.8v2.4" stroke="#4d555c" stroke-width="1.1" stroke-linecap="round"/></svg>';
      }
      if (kind === 'home') {
        return '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M2.8 7.4 8 3.1l5.2 4.3V13H9.4V9.4H6.6V13H2.8z" fill="#e7b15a" stroke="#8a5a16"/></svg>';
      }
      if (kind === 'applications') {
        return '<svg viewBox="0 0 16 16" aria-hidden="true"><rect x="2.2" y="2.2" width="5" height="5" rx="1" fill="#7f8b96"/><rect x="8.8" y="2.2" width="5" height="5" rx="1" fill="#4aa0dc"/><rect x="2.2" y="8.8" width="5" height="5" rx="1" fill="#63c36a"/><rect x="8.8" y="8.8" width="5" height="5" rx="1" fill="#e36b55"/></svg>';
      }
      return '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M2.4 4.4h4.1l1.3-1.2h5.8c.7 0 1.2.5 1.2 1.2v7.4c0 .8-.6 1.4-1.4 1.4H3.6c-.8 0-1.4-.6-1.4-1.4z" fill="#6ec0ea" stroke="#2a6f9a"/></svg>';
    }

    function getFinderSidebarLocationFileSystemObject(locationKey) {
      if (locationKey === 'macintosh-hd') {
        return macintoshHDFileSystemObject || virtualFileSystem.root || null;
      }
      if (locationKey === 'applications') {
        return typeof applicationsFileSystemObject !== 'undefined'
          ? applicationsFileSystemObject
          : null;
      }
      if (locationKey === 'documents') {
        return typeof documentsFileSystemObject !== 'undefined'
          ? documentsFileSystemObject
          : null;
      }
      if (locationKey === 'home') {
        return typeof homeFileSystemObject !== 'undefined'
          ? homeFileSystemObject
          : null;
      }
      if (locationKey === 'desktop') {
        return typeof desktopFileSystemObject !== 'undefined'
          ? desktopFileSystemObject
          : null;
      }
      if (locationKey === 'network') {
        return typeof networkFileSystemObject !== 'undefined'
          ? networkFileSystemObject
          : null;
      }
      if (locationKey === 'computer') {
        return typeof computerFileSystemObject !== 'undefined'
          ? computerFileSystemObject
          : null;
      }
      if (locationKey === 'idisk') {
        return typeof iDiskFileSystemObject !== 'undefined'
          ? iDiskFileSystemObject
          : null;
      }
      return null;
    }

    function getFinderSidebarReferencedFileSystemObject(locationKey) {
      if (locationKey === 'computer') {
        return typeof computerFileSystemObject !== 'undefined'
          ? computerFileSystemObject
          : null;
      }
      if (locationKey === 'idisk') {
        return typeof iDiskFileSystemObject !== 'undefined'
          ? iDiskFileSystemObject
          : null;
      }
      return getFinderSidebarLocationFileSystemObject(locationKey);
    }

    function createFinderSidebar(finderWindow) {
      const sidebar = document.createElement('div');
      sidebar.className = 'finder-sidebar';
      sidebar.setAttribute('role', 'navigation');
      sidebar.setAttribute('aria-label', 'Sidebar');

      const devicesLabel = document.createElement('div');
      devicesLabel.className = 'finder-sidebar-section-label';
      devicesLabel.textContent = 'DEVICES';

      const placesLabel = document.createElement('div');
      placesLabel.className = 'finder-sidebar-section-label';
      placesLabel.textContent = 'PLACES';

      function createSidebarItem(label, iconKind, locationKey) {
        const item = document.createElement('div');
        item.className = 'finder-sidebar-item';
        item.setAttribute('data-sidebar-location', locationKey);
        const icon = document.createElement('span');
        icon.className = 'finder-sidebar-icon';
        icon.innerHTML = createFinderSidebarIcon(iconKind);
        const name = document.createElement('span');
        name.textContent = label;
        item.append(icon, name);

        const referencedFileSystemObject = getFinderSidebarReferencedFileSystemObject(
          locationKey
        );
        if (referencedFileSystemObject) {
          item.setAttribute(
            'data-sidebar-object-name',
            referencedFileSystemObject.name
          );
        }

        const locationFileSystemObject = getFinderSidebarLocationFileSystemObject(
          locationKey
        );
        if (locationFileSystemObject) {
          item.classList.add('is-navigable');
          item.setAttribute('role', 'button');
          item.setAttribute('aria-label', label);
          item.addEventListener('click', (event) => {
            event.stopPropagation();
            navigateFinderWindowToDirectory(
              finderWindow,
              locationFileSystemObject
            );
            updateFinderWindowChrome(finderWindow);
          });
        } else {
          item.classList.add('is-static');
          item.setAttribute('aria-disabled', 'true');
        }
        return item;
      }

      sidebar.append(
        devicesLabel,
        createSidebarItem('iDisk', 'drive', 'idisk'),
        createSidebarItem('Network', 'network', 'network'),
        placesLabel,
        createSidebarItem('Computer', 'desktop', 'computer'),
        createSidebarItem('Home', 'home', 'home'),
        createSidebarItem('Applications', 'applications', 'applications'),
        createSidebarItem('Documents', 'documents', 'documents')
      );
      return sidebar;
    }

    function createFinderToolbar(finderWindow) {
      const toolbar = document.createElement('div');
      toolbar.className = 'finder-toolbar';
      toolbar.setAttribute('role', 'toolbar');
      toolbar.setAttribute('aria-label', 'Finder toolbar');

      const navGroup = document.createElement('div');
      navGroup.className = 'finder-toolbar-nav';

      const backButton = document.createElement('button');
      backButton.type = 'button';
      backButton.className = 'finder-toolbar-nav-button finder-toolbar-back';
      backButton.setAttribute('aria-label', 'Back');
      backButton.innerHTML = '<svg viewBox="0 0 12 12" aria-hidden="true"><path d="M8.2 2.2 3.6 6l4.6 3.8"/></svg>';
      backButton.addEventListener('click', (event) => {
        event.stopPropagation();
        activateBackMenuItem();
      });

      const forwardButton = document.createElement('button');
      forwardButton.type = 'button';
      forwardButton.className = 'finder-toolbar-nav-button finder-toolbar-forward';
      forwardButton.setAttribute('aria-label', 'Forward');
      forwardButton.innerHTML = '<svg viewBox="0 0 12 12" aria-hidden="true"><path d="M3.8 2.2 8.4 6l-4.6 3.8"/></svg>';
      forwardButton.addEventListener('click', (event) => {
        event.stopPropagation();
        activateForwardMenuItem();
      });
      navGroup.append(backButton, forwardButton);

      const viewSwitcher = document.createElement('div');
      viewSwitcher.className = 'finder-view-switcher';
      viewSwitcher.setAttribute('aria-label', 'View');

      function createViewButton(mode, label, svg) {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'finder-view-button';
        button.setAttribute('data-view-mode', mode);
        button.setAttribute('aria-label', label);
        button.innerHTML = svg;
        button.addEventListener('click', (event) => {
          event.stopPropagation();
          if (mode === 'icons') {
            activateAsIconsMenuItem();
          } else if (mode === 'list') {
            activateAsListMenuItem();
          } else {
            activateAsColumnsMenuItem();
          }
        });
        return button;
      }

      viewSwitcher.append(
        createViewButton('icons', 'as Icons', '<svg viewBox="0 0 15 13" aria-hidden="true"><rect x="0" y="0" width="6" height="6" rx="1"/><rect x="9" y="0" width="6" height="6" rx="1"/><rect x="0" y="7" width="6" height="6" rx="1"/><rect x="9" y="7" width="6" height="6" rx="1"/></svg>'),
        createViewButton('list', 'as List', '<svg viewBox="0 0 15 13" aria-hidden="true"><rect x="0" y="0.5" width="3" height="3" rx="0.5"/><rect x="5" y="1.2" width="10" height="1.6" rx="0.4"/><rect x="0" y="5" width="3" height="3" rx="0.5"/><rect x="5" y="5.7" width="10" height="1.6" rx="0.4"/><rect x="0" y="9.5" width="3" height="3" rx="0.5"/><rect x="5" y="10.2" width="10" height="1.6" rx="0.4"/></svg>'),
        createViewButton('columns', 'as Columns', '<svg viewBox="0 0 15 13" aria-hidden="true"><rect x="0" y="0" width="4" height="13" rx="0.6"/><rect x="5.5" y="0" width="4" height="13" rx="0.6"/><rect x="11" y="0" width="4" height="13" rx="0.6"/></svg>')
      );

      const actionButton = document.createElement('button');
      actionButton.type = 'button';
      actionButton.className = 'finder-action-button';
      actionButton.setAttribute('aria-label', 'Action');
      actionButton.setAttribute('aria-disabled', 'true');
      actionButton.setAttribute('tabindex', '-1');
      actionButton.innerHTML = '<svg viewBox="0 0 14 14" aria-hidden="true"><circle cx="7" cy="7" r="2.1"/><path d="M7 1.4v1.7M7 10.9v1.7M1.4 7h1.7M10.9 7h1.7M2.8 2.8l1.2 1.2M10 10l1.2 1.2M2.8 11.2 4 10M10 4l1.2-1.2"/></svg>';

      const searchField = document.createElement('div');
      searchField.className = 'finder-search-field';
      searchField.setAttribute('role', 'searchbox');
      searchField.setAttribute('aria-label', 'Search');
      searchField.setAttribute('aria-disabled', 'true');
      searchField.setAttribute('aria-readonly', 'true');

      toolbar.append(navGroup, viewSwitcher, actionButton, searchField);
      return toolbar;
    }

    function createFinderStatusBar() {
      const statusBar = document.createElement('div');
      statusBar.className = 'finder-status-bar';
      const count = document.createElement('span');
      count.className = 'finder-status-count';
      count.textContent = '0 items';
      const space = document.createElement('span');
      space.className = 'finder-status-space';
      space.textContent = '120 GB available';
      statusBar.append(count, space);
      return statusBar;
    }

    function updateFinderWindowChrome(finderWindow) {
      if (!finderWindow || finderWindow.getAttribute('data-finder-window') !== 'true') {
        return;
      }

      const directoryFileSystemObject = finderWindowFileSystemObjects.get(
        finderWindow
      );
      const itemCount = directoryFileSystemObject
        ? getFileSystemObjectChildren(directoryFileSystemObject).length
        : 0;
      const count = finderWindow.querySelector('.finder-status-count');
      if (count) {
        count.textContent = `${itemCount} ${itemCount === 1 ? 'item' : 'items'}`;
      }

      const viewMode = finderWindow.getAttribute('data-view-mode') || 'icons';
      finderWindow.querySelectorAll('.finder-view-button').forEach((button) => {
        button.classList.toggle(
          'is-selected',
          button.getAttribute('data-view-mode') === viewMode
        );
      });

      const backHistory = finderWindowBackHistory.get(finderWindow);
      const forwardHistory = finderWindowForwardHistory.get(finderWindow);
      const backButton = finderWindow.querySelector('.finder-toolbar-back');
      const forwardButton = finderWindow.querySelector('.finder-toolbar-forward');
      if (backButton) {
        backButton.disabled = !backHistory || backHistory.length === 0;
      }
      if (forwardButton) {
        forwardButton.disabled = !forwardHistory || forwardHistory.length === 0;
      }

      finderWindow.querySelectorAll('.finder-sidebar-item[data-sidebar-location]').forEach((item) => {
        const locationFileSystemObject = getFinderSidebarLocationFileSystemObject(
          item.getAttribute('data-sidebar-location')
        );
        item.classList.toggle(
          'is-selected',
          Boolean(
            locationFileSystemObject &&
            locationFileSystemObject === directoryFileSystemObject
          )
        );
      });
    }

    function attachFilesystemFinderChrome(finderWindow, titleId, titleText) {
      const titleBar = document.createElement('div');
      titleBar.className = 'finder-title-bar';

      const closeButton = document.createElement('button');
      closeButton.type = 'button';
      closeButton.className = 'finder-close';
      closeButton.setAttribute('aria-label', 'Close');
      closeButton.addEventListener('click', () => {
        closeFinderWindow(finderWindow);
      });

      const title = document.createElement('div');
      title.id = titleId;
      title.className = 'finder-title';
      title.textContent = titleText;
      titleBar.append(closeButton, title);

      const toolbar = createFinderToolbar(finderWindow);
      const body = document.createElement('div');
      body.className = 'finder-body';
      const sidebar = createFinderSidebar(finderWindow);
      const main = document.createElement('div');
      main.className = 'finder-main';
      const content = document.createElement('div');
      content.className = 'finder-content';
      content.setAttribute('role', 'listbox');
      content.setAttribute('aria-label', titleText);
      main.appendChild(content);
      body.append(sidebar, main);

      const statusBar = createFinderStatusBar();
      finderWindow.append(titleBar, toolbar, body, statusBar);
      applyFinderWindowIconSize(finderWindow, getFinderWindowIconSize(finderWindow));
      applyFinderWindowTextSize(finderWindow, getFinderWindowTextSize(finderWindow));
      applyFinderWindowLabelPosition(finderWindow, getFinderWindowLabelPosition(finderWindow));
      applyFinderWindowShowItemInfo(finderWindow, getFinderWindowShowItemInfo(finderWindow));
      applyFinderWindowShowIconPreview(finderWindow, getFinderWindowShowIconPreview(finderWindow));
      updateFinderWindowChrome(finderWindow);
      return { titleBar, content };
    }

    function showDynamicFolderWindow(folderFileSystemObject) {
      const existingFolderWindow = dynamicFolderWindowsByFileSystemObject.get(
        folderFileSystemObject
      );
      if (existingFolderWindow && existingFolderWindow.isConnected) {
        focusFinderWindow(existingFolderWindow);
        return;
      }
      if (existingFolderWindow) {
        dynamicFolderWindowsByFileSystemObject.delete(folderFileSystemObject);
      }

      dynamicFolderWindowSequence += 1;
      const folderWindow = document.createElement('section');
      folderWindow.id = `dynamic-folder-window-${dynamicFolderWindowSequence}`;
      folderWindow.className = 'finder-window dynamic-folder-window';
      folderWindow.style.transform = `translate(calc(-50% + ${
        42 + ((dynamicFolderWindowSequence - 1) % 5) * 26
      }px), calc(-50% + ${
        38 + ((dynamicFolderWindowSequence - 1) % 5) * 24
      }px))`;
      folderWindow.setAttribute('role', 'dialog');
      folderWindow.setAttribute(
        'aria-labelledby',
        `dynamic-folder-window-title-${dynamicFolderWindowSequence}`
      );
      folderWindow.setAttribute('data-finder-window', 'true');
      finderWindowFileSystemObjects.set(folderWindow, folderFileSystemObject);

      const { titleBar, content } = attachFilesystemFinderChrome(
        folderWindow,
        `dynamic-folder-window-title-${dynamicFolderWindowSequence}`,
        folderFileSystemObject.name
      );

      appendUnrepresentedFileSystemItems(
        content,
        folderFileSystemObject
      );
      content.addEventListener('click', (event) => {
        if (event.target === content) {
          clearDirectFinderItemSelection(content);
        }
      });
      dynamicFolderWindowsByFileSystemObject.set(
        folderFileSystemObject,
        folderWindow
      );
      dynamicFolderFileSystemObjectsByWindow.set(
        folderWindow,
        folderFileSystemObject
      );
      updateFinderWindowChrome(folderWindow);
      document.body.appendChild(folderWindow);
      enableWindowFocus(folderWindow);
      makeWindowDraggable(folderWindow, titleBar);
    }




