    function findSimulatedHelpTopic(source, title) {
      return simulatedHelpTopics.find((topic) => (
        topic.source === source && topic.title === title
      )) || null;
    }

    function searchSimulatedHelpTopics(query) {
      const needle = String(query || '').trim().toLowerCase();
      if (!needle) {
        return [];
      }
      return simulatedHelpTopics.filter((topic) => (
        topic.title.toLowerCase().includes(needle) ||
        topic.body.toLowerCase().includes(needle)
      ));
    }

    function setHelpViewerTopic(windowId, itemSelector, titleSelector, copySelector, source, title) {
      const helpWindow = document.getElementById(windowId);
      if (!helpWindow) {
        return;
      }
      const topic = findSimulatedHelpTopic(source, title);
      const articleTitle = helpWindow.querySelector(titleSelector);
      const articleCopy = helpWindow.querySelector(copySelector);
      if (articleTitle) {
        articleTitle.textContent = title;
      }
      if (articleCopy) {
        articleCopy.textContent = topic ? topic.body : '';
      }
      helpWindow.querySelectorAll(itemSelector).forEach((item) => {
        item.classList.toggle('is-shown', item.textContent === title);
      });
    }

    function setMacHelpTopic(title) {
      setHelpViewerTopic(
        'mac-help-window',
        '.mac-help-index-item',
        '.mac-help-article-title',
        '.mac-help-article-copy',
        'mac-help',
        title
      );
    }

    function setTigerHelpTopic(title) {
      setHelpViewerTopic(
        'tiger-help-window',
        '.tiger-help-index-item',
        '.tiger-help-article-title',
        '.tiger-help-article-copy',
        'tiger-help',
        title
      );
      const tigerHelpWindow = document.getElementById('tiger-help-window');
      const appleLogo = tigerHelpWindow && tigerHelpWindow.querySelector('.tiger-help-apple-logo');
      if (appleLogo) {
        appleLogo.hidden = title !== 'Mac OS X';
      }
    }

    function openSimulatedHelpTopic(topic) {
      if (!topic) {
        return;
      }
      if (topic.source === 'mac-help') {
        showMacHelpWindow();
        setMacHelpTopic(topic.title);
        return;
      }
      showTigerHelpWindow();
      setTigerHelpTopic(topic.title);
    }

    function renderHelpSearchResults(resultsArea, topics) {
      resultsArea.replaceChildren();
      if (topics.length === 0) {
        const empty = document.createElement('div');
        empty.className = 'help-search-empty';
        empty.textContent = 'No matching topics found';
        resultsArea.appendChild(empty);
        return;
      }

      topics.forEach((topic) => {
        const result = document.createElement('button');
        result.type = 'button';
        result.className = 'help-search-result';
        result.setAttribute('aria-label', `${topic.title}, ${topic.viewer}`);

        const title = document.createElement('div');
        title.className = 'help-search-result-title';
        title.textContent = topic.title;

        const source = document.createElement('div');
        source.className = 'help-search-result-source';
        source.textContent = topic.viewer;

        result.append(title, source);
        result.addEventListener('click', () => {
          openSimulatedHelpTopic(topic);
        });
        resultsArea.appendChild(result);
      });
    }

    function runHelpSearch(searchField, resultsArea) {
      const query = searchField.value;
      if (!String(query || '').trim()) {
        resultsArea.replaceChildren();
        return;
      }
      renderHelpSearchResults(resultsArea, searchSimulatedHelpTopics(query));
    }

    function showHelpSearchWindow() {
      const existingHelpSearchWindow = document.getElementById('help-search-window');
      if (existingHelpSearchWindow) {
        focusFinderWindow(existingHelpSearchWindow);
        const existingField = existingHelpSearchWindow.querySelector('.help-search-field');
        if (existingField) {
          existingField.focus();
        }
        return;
      }

      const helpSearchWindow = document.createElement('section');
      helpSearchWindow.id = 'help-search-window';
      helpSearchWindow.className = 'finder-window help-search-window';
      helpSearchWindow.setAttribute('role', 'dialog');
      helpSearchWindow.setAttribute('aria-labelledby', 'help-search-window-title');

      const titleBar = document.createElement('div');
      titleBar.className = 'finder-title-bar';

      const closeButton = document.createElement('button');
      closeButton.type = 'button';
      closeButton.className = 'finder-close';
      closeButton.setAttribute('aria-label', 'Close');
      closeButton.addEventListener('click', () => {
        closeFinderWindow(helpSearchWindow);
      });

      const title = document.createElement('div');
      title.id = 'help-search-window-title';
      title.className = 'finder-title';
      title.textContent = 'Help Search';

      const content = document.createElement('div');
      content.className = 'finder-content help-search-content';
      content.setAttribute('aria-label', 'Help Search');

      const controls = document.createElement('div');
      controls.className = 'help-search-controls';

      const searchField = document.createElement('input');
      searchField.type = 'search';
      searchField.className = 'help-search-field';
      searchField.setAttribute('aria-label', 'Search');
      searchField.setAttribute('autocomplete', 'off');
      searchField.setAttribute('spellcheck', 'false');

      const searchButton = document.createElement('button');
      searchButton.type = 'button';
      searchButton.className = 'help-search-button';
      searchButton.textContent = 'Search';

      const resultsArea = document.createElement('div');
      resultsArea.className = 'help-search-results';
      resultsArea.setAttribute('aria-label', 'Search results');

      searchButton.addEventListener('click', () => {
        runHelpSearch(searchField, resultsArea);
      });
      searchField.addEventListener('keydown', (event) => {
        if (event.key === 'Enter') {
          event.preventDefault();
          runHelpSearch(searchField, resultsArea);
        }
      });

      controls.append(searchField, searchButton);
      content.append(controls, resultsArea);
      titleBar.append(closeButton, title);
      helpSearchWindow.append(titleBar, content);
      document.body.appendChild(helpSearchWindow);
      enableWindowFocus(helpSearchWindow);
      makeWindowDraggable(helpSearchWindow, titleBar);
      searchField.focus();
    }

    function activateHelpSearchMenuItem() {
      closeAllMenuDropdowns();
      showHelpSearchWindow();
    }

