    function getRunningSimulatedApplications() {
      const runningApplications = [];
      const finderOwnedWindows = [...document.querySelectorAll('.finder-window')].filter((finderWindow) => (
        isFinderOwnedWindow(finderWindow) && finderWindow.isConnected
      ));
      if (finderOwnedWindows.length > 0) {
        runningApplications.push({
          id: 'finder',
          name: 'Finder'
        });
      }

      const safariWindow = document.getElementById('safari-window');
      if (safariWindow && safariWindow.isConnected) {
        runningApplications.push({
          id: 'safari',
          name: safariFileSystemObject.name
        });
      }

      const textEditWindow = document.getElementById('textedit-window');
      if (textEditWindow && textEditWindow.isConnected) {
        runningApplications.push({
          id: 'textedit',
          name: textEditFileSystemObject.name
        });
      }

      const calculatorWindow = document.getElementById('calculator-window');
      if (calculatorWindow && calculatorWindow.isConnected) {
        runningApplications.push({
          id: 'calculator',
          name: calculatorApplicationIdentity.name
        });
      }

      const iTunesWindow = document.getElementById('itunes-window');
      if (iTunesWindow && iTunesWindow.isConnected) {
        runningApplications.push({
          id: 'itunes',
          name: iTunesApplicationIdentity.name
        });
      }

      const pagesWindow = document.getElementById('pages-window');
      if (pagesWindow && pagesWindow.isConnected) {
        runningApplications.push({
          id: 'pages',
          name: pagesApplicationIdentity.name
        });
      }

      const keynoteWindow = document.getElementById('keynote-window');
      if (keynoteWindow && keynoteWindow.isConnected) {
        runningApplications.push({
          id: 'keynote',
          name: keynoteApplicationIdentity.name
        });
      }

      const numbersWindow = document.getElementById('numbers-window');
      if (numbersWindow && numbersWindow.isConnected) {
        runningApplications.push({
          id: 'numbers',
          name: numbersApplicationIdentity.name
        });
      }

      const iPhotoWindow = document.getElementById('iphoto-window');
      if (iPhotoWindow && iPhotoWindow.isConnected) {
        runningApplications.push({
          id: 'iphoto',
          name: iPhotoApplicationIdentity.name
        });
      }

      const iMovieWindow = document.getElementById('imovie-window');
      if (iMovieWindow && iMovieWindow.isConnected) {
        runningApplications.push({
          id: 'imovie',
          name: iMovieApplicationIdentity.name
        });
      }

      const garageBandWindow = document.getElementById('garageband-window');
      if (garageBandWindow && garageBandWindow.isConnected) {
        runningApplications.push({
          id: 'garageband',
          name: garageBandApplicationIdentity.name
        });
      }

      const iDVDWindow = document.getElementById('idvd-window');
      if (iDVDWindow && iDVDWindow.isConnected) {
        runningApplications.push({
          id: 'idvd',
          name: iDVDApplicationIdentity.name
        });
      }

      return runningApplications;
    }

    function getSelectedForceQuitApplicationId(forceQuitWindow) {
      return forceQuitWindow
        ? forceQuitWindow.getAttribute('data-selected-application')
        : null;
    }

    function syncForceQuitButton(forceQuitWindow) {
      if (!forceQuitWindow) {
        return;
      }
      const forceQuitButton = forceQuitWindow.querySelector('#force-quit-button');
      if (!forceQuitButton) {
        return;
      }
      const selectedApplicationId = getSelectedForceQuitApplicationId(forceQuitWindow);
      const isAvailable = getRunningSimulatedApplications().some((application) => (
        application.id === selectedApplicationId
      ));
      forceQuitButton.disabled = !isAvailable;
      forceQuitButton.setAttribute('aria-disabled', String(!isAvailable));
    }

    function selectForceQuitApplication(forceQuitWindow, applicationId) {
      if (!forceQuitWindow) {
        return;
      }
      const runningApplications = getRunningSimulatedApplications();
      const isAvailable = runningApplications.some((application) => (
        application.id === applicationId
      ));
      if (isAvailable) {
        forceQuitWindow.setAttribute('data-selected-application', applicationId);
      } else {
        forceQuitWindow.removeAttribute('data-selected-application');
      }
      forceQuitWindow.querySelectorAll('.force-quit-application').forEach((applicationItem) => {
        const isSelected = isAvailable && applicationItem.getAttribute('data-application-id') === applicationId;
        applicationItem.classList.toggle('is-selected', isSelected);
        applicationItem.setAttribute('aria-selected', String(isSelected));
      });
      syncForceQuitButton(forceQuitWindow);
    }

    function renderForceQuitApplicationsList(forceQuitWindow) {
      if (!forceQuitWindow) {
        return;
      }
      const applicationList = forceQuitWindow.querySelector('.force-quit-application-list');
      if (!applicationList) {
        return;
      }
      const previouslySelectedApplicationId = getSelectedForceQuitApplicationId(forceQuitWindow);
      const runningApplications = getRunningSimulatedApplications();
      applicationList.replaceChildren();
      runningApplications.forEach((application) => {
        const applicationItem = document.createElement('button');
        applicationItem.type = 'button';
        applicationItem.className = 'force-quit-application';
        applicationItem.setAttribute('role', 'option');
        applicationItem.setAttribute('data-application-id', application.id);
        applicationItem.setAttribute('aria-selected', 'false');
        applicationItem.textContent = application.name;
        applicationItem.addEventListener('click', (event) => {
          event.stopPropagation();
          selectForceQuitApplication(forceQuitWindow, application.id);
        });
        applicationList.appendChild(applicationItem);
      });
      selectForceQuitApplication(forceQuitWindow, previouslySelectedApplicationId);
    }

    function forceQuitSelectedApplication() {
      const forceQuitWindow = document.getElementById('force-quit-window');
      if (!forceQuitWindow) {
        return;
      }
      const selectedApplicationId = getSelectedForceQuitApplicationId(forceQuitWindow);
      const selectedApplication = getRunningSimulatedApplications().find((application) => (
        application.id === selectedApplicationId
      ));
      if (!selectedApplication) {
        return;
      }
      if (selectedApplication.id === 'finder') {
        quitFinderWindows();
      } else if (selectedApplication.id === 'safari') {
        const safariWindow = document.getElementById('safari-window');
        if (safariWindow && safariWindow.isConnected) {
          closeFinderWindow(safariWindow);
        }
      } else if (selectedApplication.id === 'textedit') {
        const textEditWindow = document.getElementById('textedit-window');
        if (textEditWindow && textEditWindow.isConnected) {
          closeFinderWindow(textEditWindow);
        }
      } else if (selectedApplication.id === 'calculator') {
        const calculatorWindow = document.getElementById('calculator-window');
        if (calculatorWindow && calculatorWindow.isConnected) {
          closeFinderWindow(calculatorWindow);
        }
      } else if (selectedApplication.id === 'itunes') {
        const iTunesWindow = document.getElementById('itunes-window');
        if (iTunesWindow && iTunesWindow.isConnected) {
          closeFinderWindow(iTunesWindow);
        }
      } else if (selectedApplication.id === 'pages') {
        const pagesWindow = document.getElementById('pages-window');
        if (pagesWindow && pagesWindow.isConnected) {
          closeFinderWindow(pagesWindow);
        }
      } else if (selectedApplication.id === 'keynote') {
        const keynoteWindow = document.getElementById('keynote-window');
        if (keynoteWindow && keynoteWindow.isConnected) {
          closeFinderWindow(keynoteWindow);
        }
      } else if (selectedApplication.id === 'numbers') {
        const numbersWindow = document.getElementById('numbers-window');
        if (numbersWindow && numbersWindow.isConnected) {
          closeFinderWindow(numbersWindow);
        }
      } else if (selectedApplication.id === 'iphoto') {
        const iPhotoWindow = document.getElementById('iphoto-window');
        if (iPhotoWindow && iPhotoWindow.isConnected) {
          closeFinderWindow(iPhotoWindow);
        }
      } else if (selectedApplication.id === 'imovie') {
        const iMovieWindow = document.getElementById('imovie-window');
        if (iMovieWindow && iMovieWindow.isConnected) {
          closeFinderWindow(iMovieWindow);
        }
      } else if (selectedApplication.id === 'garageband') {
        const garageBandWindow = document.getElementById('garageband-window');
        if (garageBandWindow && garageBandWindow.isConnected) {
          closeFinderWindow(garageBandWindow);
        }
      } else if (selectedApplication.id === 'idvd') {
        const iDVDWindow = document.getElementById('idvd-window');
        if (iDVDWindow && iDVDWindow.isConnected) {
          closeFinderWindow(iDVDWindow);
        }
      }
      forceQuitWindow.removeAttribute('data-selected-application');
      renderForceQuitApplicationsList(forceQuitWindow);
    }

    function showForceQuitWindow() {
      const existingForceQuitWindow = document.getElementById('force-quit-window');
      if (existingForceQuitWindow && existingForceQuitWindow.isConnected) {
        focusFinderWindow(existingForceQuitWindow);
        renderForceQuitApplicationsList(existingForceQuitWindow);
        return;
      }

      const forceQuitWindow = document.createElement('section');
      forceQuitWindow.id = 'force-quit-window';
      forceQuitWindow.className = 'finder-window force-quit-window';
      forceQuitWindow.setAttribute('role', 'dialog');
      forceQuitWindow.setAttribute('aria-labelledby', 'force-quit-window-title');
      forceQuitWindow.setAttribute('data-force-quit-window', 'true');

      const titleBar = document.createElement('div');
      titleBar.className = 'finder-title-bar';

      const closeButton = document.createElement('button');
      closeButton.type = 'button';
      closeButton.className = 'finder-close';
      closeButton.setAttribute('aria-label', 'Close');
      closeButton.addEventListener('click', () => {
        closeFinderWindow(forceQuitWindow);
      });

      const title = document.createElement('div');
      title.id = 'force-quit-window-title';
      title.className = 'finder-title';
      title.textContent = 'Force Quit Applications';

      const content = document.createElement('div');
      content.className = 'finder-content force-quit-content';
      content.setAttribute('aria-label', 'Force Quit Applications');

      const copy = document.createElement('p');
      copy.className = 'force-quit-copy';
      copy.textContent = "If an application doesn't respond for a while, select its name and click Force Quit.";

      const applicationList = document.createElement('div');
      applicationList.className = 'force-quit-application-list';
      applicationList.setAttribute('role', 'listbox');
      applicationList.setAttribute('aria-label', 'Running applications');

      const actions = document.createElement('div');
      actions.className = 'force-quit-actions';

      const forceQuitButton = document.createElement('button');
      forceQuitButton.type = 'button';
      forceQuitButton.id = 'force-quit-button';
      forceQuitButton.className = 'force-quit-button';
      forceQuitButton.textContent = 'Force Quit';
      forceQuitButton.disabled = true;
      forceQuitButton.setAttribute('aria-disabled', 'true');
      forceQuitButton.addEventListener('click', (event) => {
        event.stopPropagation();
        forceQuitSelectedApplication();
      });

      actions.appendChild(forceQuitButton);
      content.append(copy, applicationList, actions);
      titleBar.append(closeButton, title);
      forceQuitWindow.append(titleBar, content);
      document.body.appendChild(forceQuitWindow);
      enableWindowFocus(forceQuitWindow);
      makeWindowDraggable(forceQuitWindow, titleBar);
      renderForceQuitApplicationsList(forceQuitWindow);
    }

