    function getPreferredNewFinderWindowFileSystemObject() {
      if (simulatedNewFinderWindowLocation === 'home') {
        return homeFileSystemObject;
      }
      if (simulatedNewFinderWindowLocation === 'applications') {
        return applicationsFileSystemObject;
      }
      if (simulatedNewFinderWindowLocation === 'documents') {
        return documentsFileSystemObject;
      }
      return macintoshHDFileSystemObject;
    }

    function openPreferredNewFinderWindow() {
      if (restoreFinderWindowsHiddenByFinderIfAny()) {
        return;
      }
      if (simulatedNewFinderWindowLocation === 'home') {
        showDynamicFolderWindow(homeFileSystemObject);
        return;
      }
      if (simulatedNewFinderWindowLocation === 'applications') {
        showApplicationsWindow();
        return;
      }
      if (simulatedNewFinderWindowLocation === 'documents') {
        showDocumentsWindow();
        return;
      }
      showMacintoshHDWindow();
    }

    function syncFinderPreferencesLocationControl(preferencesWindow) {
      if (!preferencesWindow || !preferencesWindow.isConnected) {
        return;
      }
      preferencesWindow.querySelectorAll('.finder-preferences-location-choice').forEach((choice) => {
        const isShown = choice.getAttribute('data-new-finder-location') === simulatedNewFinderWindowLocation;
        choice.classList.toggle('is-shown', isShown);
        choice.setAttribute('aria-pressed', String(isShown));
      });
    }

    function applySimulatedNewFinderWindowLocation(locationKey) {
      const nextLocation = simulatedNewFinderWindowLocations.includes(locationKey)
        ? locationKey
        : defaultSimulatedNewFinderWindowLocation;
      simulatedNewFinderWindowLocation = nextLocation;
      const preferencesWindow = document.getElementById('finder-preferences-window');
      syncFinderPreferencesLocationControl(preferencesWindow);
    }

    function syncSystemPreferencesAppearanceControl(preferencesWindow) {
      if (!preferencesWindow || !preferencesWindow.isConnected) {
        return;
      }
      preferencesWindow.querySelectorAll('.system-preferences-appearance-choice').forEach((choice) => {
        const isShown = choice.getAttribute('data-appearance') === simulatedAppearance;
        choice.classList.toggle('is-shown', isShown);
        choice.setAttribute('aria-pressed', String(isShown));
      });
    }

    function applySimulatedAppearance(appearanceKey) {
      const nextAppearance = simulatedAppearances.includes(appearanceKey)
        ? appearanceKey
        : defaultSimulatedAppearance;
      simulatedAppearance = nextAppearance;
      document.documentElement.setAttribute('data-appearance', nextAppearance);
      syncSystemPreferencesAppearanceControl(
        document.getElementById('system-preferences-window')
      );
    }

    function showSystemPreferencesWindow() {
      const existingSystemPreferencesWindow = document.getElementById('system-preferences-window');
      if (existingSystemPreferencesWindow && existingSystemPreferencesWindow.isConnected) {
        focusFinderWindow(existingSystemPreferencesWindow);
        syncSystemPreferencesAppearanceControl(existingSystemPreferencesWindow);
        return;
      }

      const preferencesWindow = document.createElement('section');
      preferencesWindow.id = 'system-preferences-window';
      preferencesWindow.className = 'finder-window system-preferences-window';
      preferencesWindow.setAttribute('role', 'dialog');
      preferencesWindow.setAttribute('aria-labelledby', 'system-preferences-window-title');
      preferencesWindow.setAttribute('data-system-preferences-window', 'true');

      const titleBar = document.createElement('div');
      titleBar.className = 'finder-title-bar';

      const closeButton = document.createElement('button');
      closeButton.type = 'button';
      closeButton.className = 'finder-close';
      closeButton.setAttribute('aria-label', 'Close');
      closeButton.addEventListener('click', () => {
        closeFinderWindow(preferencesWindow);
      });

      const title = document.createElement('div');
      title.id = 'system-preferences-window-title';
      title.className = 'finder-title';
      title.textContent = 'System Preferences';

      const content = document.createElement('div');
      content.className = 'finder-content system-preferences-content';
      content.setAttribute('aria-label', 'System Preferences');

      const section = document.createElement('div');
      section.className = 'system-preferences-section';

      const heading = document.createElement('div');
      heading.className = 'system-preferences-section-heading';
      heading.textContent = 'General';

      const appearanceRow = document.createElement('div');
      appearanceRow.className = 'system-preferences-row';

      const appearanceLabel = document.createElement('div');
      appearanceLabel.className = 'system-preferences-label';
      appearanceLabel.textContent = 'Appearance:';

      const appearanceList = document.createElement('div');
      appearanceList.className = 'system-preferences-appearance-list';
      appearanceList.setAttribute('role', 'radiogroup');
      appearanceList.setAttribute('aria-label', 'Appearance');

      const appearanceLabels = {
        aqua: 'Aqua',
        graphite: 'Graphite'
      };
      simulatedAppearances.forEach((appearanceKey) => {
        const choice = document.createElement('button');
        choice.type = 'button';
        choice.className = 'system-preferences-appearance-choice';
        choice.setAttribute('data-appearance', appearanceKey);
        choice.setAttribute('role', 'radio');
        choice.setAttribute('aria-label', appearanceLabels[appearanceKey]);
        choice.setAttribute('aria-pressed', 'false');
        const radio = document.createElement('span');
        radio.className = 'system-preferences-radio';
        radio.setAttribute('aria-hidden', 'true');
        const name = document.createElement('span');
        name.textContent = appearanceLabels[appearanceKey];
        choice.append(radio, name);
        choice.addEventListener('click', (event) => {
          event.stopPropagation();
          applySimulatedAppearance(appearanceKey);
        });
        appearanceList.appendChild(choice);
      });

      appearanceRow.append(appearanceLabel, appearanceList);

      const finderRow = document.createElement('div');
      finderRow.className = 'system-preferences-row';

      const finderLabel = document.createElement('div');
      finderLabel.className = 'system-preferences-label';
      finderLabel.textContent = 'Finder:';

      const finderButton = document.createElement('button');
      finderButton.type = 'button';
      finderButton.id = 'system-preferences-finder-button';
      finderButton.className = 'system-preferences-finder-button';
      finderButton.textContent = 'Finder Preferences…';
      finderButton.addEventListener('click', (event) => {
        event.stopPropagation();
        showFinderPreferencesWindow();
      });

      finderRow.append(finderLabel, finderButton);
      section.append(heading, appearanceRow, finderRow);
      content.appendChild(section);
      titleBar.append(closeButton, title);
      preferencesWindow.append(titleBar, content);
      document.body.appendChild(preferencesWindow);
      enableWindowFocus(preferencesWindow);
      makeWindowDraggable(preferencesWindow, titleBar);
      syncSystemPreferencesAppearanceControl(preferencesWindow);
    }

